1	import { applyEdit, BlockId, VoxelWorld } from "@/lib/world";
2	
3	/**
4	 * Tracks player edits to the generated world as deltas against the worldgen
5	 * baseline — the heart of the save format. A block restored to its original
6	 * value drops out of the delta set, keeping saves minimal.
7	 *
8	 * The tracker also journals every write since the last drain: a multiplayer
9	 * server broadcasts exactly that journal each tick, because gameplay events
10	 * alone can't reconstruct multi-cell edits (an explosion crater, a kelp
11	 * stalk refilling with water, a door's two cells).
12	 */
13	export type DetailedEdit = { idx: number; block: number; prev: number };
14	
15	export type BlockChangeTracker = {
16	  /** Tracked write: updates the world and the delta set. */
17	  set(x: number, y: number, z: number, block: BlockId): void;
18	  /** Replays saved deltas onto a freshly generated world (boot only). */
19	  applySavedChanges(changes: Array<[number, number]>): void;
20	  /** Current deltas as [voxelIndex, blockId] pairs, ready to persist. */
21	  changes(): Array<[number, number]>;
22	  /** Every write since the last drain (a server's per-tick block broadcast). */
23	  drainEdits(): Array<[number, number]>;
24	  /** Same drain window, with each cell's pre-window value — what a client's prediction ledger needs to revert. */
25	  drainEditsDetailed(): DetailedEdit[];
26	};
27	
28	export function createBlockChangeTracker(world: VoxelWorld): BlockChangeTracker {
29	  const changedBlocks = new Map<number, number>();
30	  const baselineByIndex = new Map<number, number>();
31	  // Last-write-wins within a tick window (prev = the pre-window value, kept
32	  // across same-cell rewrites); drained by the server each tick — or by a
33	  // replica capturing its own predicted edits.
34	  let editJournal = new Map<number, { block: number; prev: number }>();
35	
