  const changedBlocks = new Map<number, number>();
  const baselineByIndex = new Map<number, number>();
  // Last-write-wins within a tick window (prev = the pre-window value, kept
  // across same-cell rewrites); drained by the server each tick — or by a
  // replica capturing its own predicted edits.
  let editJournal = new Map<number, { block: number; prev: number }>();

  return {
    set(x, y, z, block) {
      if (!world.inBounds(x, y, z)) return;
      const idx = world.index(x, y, z);
      if (!baselineByIndex.has(idx)) baselineByIndex.set(idx, world.get(x, y, z));
      const prev = editJournal.get(idx)?.prev ?? world.get(x, y, z);
      world.set(x, y, z, block);
      // Patch lighting locally now the block changed. This is the single
      // chokepoint for every gameplay edit (mining, doors, farming, crop
      // growth), so each one relights without the renderer doing anything; the
      // load path (applySavedChanges) bypasses this and the full bake covers it.
      applyEdit(world, world.light, x, y, z);
      const baseline = baselineByIndex.get(idx) ?? BlockId.Air;
      if (block === baseline) changedBlocks.delete(idx);
      else changedBlocks.set(idx, block);
      editJournal.set(idx, { block, prev });
    },

    applySavedChanges(changes) {
      const layer = world.sizeX * world.sizeZ;
      for (const [idx, block] of changes) {
        const y = Math.floor(idx / layer);
        const rem = idx - y * layer;
        const z = Math.floor(rem / world.sizeX);
        const x = rem - z * world.sizeX;
        if (!world.inBounds(x, y, z)) continue;
        world.set(x, y, z, block as BlockId);
        changedBlocks.set(idx, block);
      }
    },

    changes() {
      return [...changedBlocks.entries()];
    },

    drainEdits() {
      if (editJournal.size === 0) return [];
      const drained = [...editJournal.entries()].map(([idx, e]): [number, number] => [idx, e.block]);
      editJournal = new Map();
      return drained;
    },

    drainEditsDetailed() {
      if (editJournal.size === 0) return [];
      const drained = [...editJournal.entries()].map(([idx, e]) => ({ idx, block: e.block, prev: e.prev }));
      editJournal = new Map();
      return drained;
    }
  };
}

import { BiomeId, BlockId, WORLD_SIZE_X, WORLD_SIZE_Y, WORLD_SIZE_Z } from "./blocks";
import { isDoorBlock } from "./doors";
import { isRailBlock } from "./rails";
import { isRedstoneOverlay } from "./redstone";
import { portableSin } from "./noise";

/**
 * Voxel data store plus cheap world queries. Terrain generation lives in
 * generation.ts, meshing in meshing.ts, raycast/collision in queries.ts.
 *
 * ⚠ Save-format invariants: saves address voxels through index(), and getBiome()
 * feeds terrain generation. Changing either breaks every existing save — see
 * generation.test.ts.
 */
export class VoxelWorld {
  readonly sizeX: number;
  readonly sizeY: number;
  readonly sizeZ: number;
  readonly seed: number;
  readonly blocks: Uint8Array;
  /**
   * Per-voxel light, packed (skyLight << 4) | blockLight, 0..15 each. A DERIVED
   * cache (never serialized): computeFullLight bakes it from blocks at load and
   * applyEdit patches it on block edits — see lighting.ts. Starts dark; the
   * engine bakes it once the block grid is final.
   */
  light: Uint8Array;

  constructor(sizeX = WORLD_SIZE_X, sizeY = WORLD_SIZE_Y, sizeZ = WORLD_SIZE_Z, seed = 1337) {
    this.sizeX = sizeX;
    this.sizeY = sizeY;
    this.sizeZ = sizeZ;
    this.seed = seed;
    this.blocks = new Uint8Array(sizeX * sizeY * sizeZ);
    this.light = new Uint8Array(sizeX * sizeY * sizeZ);
  }

  index(x: number, y: number, z: number): number {
    return x + z * this.sizeX + y * this.sizeX * this.sizeZ;
  }

  inBounds(x: number, y: number, z: number): boolean {
    return x >= 0 && y >= 0 && z >= 0 && x < this.sizeX && y < this.sizeY && z < this.sizeZ;
  }

  get(x: number, y: number, z: number): number {
    if (!this.inBounds(x, y, z)) return BlockId.Air;
    return this.blocks[this.index(x, y, z)];
  }

  set(x: number, y: number, z: number, block: BlockId): void {
    if (!this.inBounds(x, y, z)) return;
    this.blocks[this.index(x, y, z)] = block;
  }

  isSolid(x: number, y: number, z: number): boolean {
    const block = this.get(x, y, z);
    // Water and the portal surface are walked into, never collided with (the
    // portal also lets the solid raycast pass — you target the frame, not it).
    return block !== BlockId.Air && block !== BlockId.Water && block !== BlockId.NetherPortal;
  }

  /** Sky-light level (0..15) at a voxel. Outside the world reads as open sky. */
  getSky(x: number, y: number, z: number): number {
    if (!this.inBounds(x, y, z)) return 15;
    return this.light[this.index(x, y, z)] >> 4;
  }

  /** Block-light level (0..15) at a voxel. Outside the world is unlit. */
  getBlockLight(x: number, y: number, z: number): number {
    if (!this.inBounds(x, y, z)) return 0;
    return this.light[this.index(x, y, z)] & 0x0f;
  }

  highestSolidY(x: number, z: number): number {
    for (let y = this.sizeY - 1; y >= 0; y -= 1) {
      const block = this.get(x, y, z);
      if (this.isSolid(x, y, z) && !isDoorBlock(block) && !isRedstoneOverlay(block) && !isRailBlock(block)) return y;
    }
    return 0;
  }

  getBiome(x: number, z: number): BiomeId {
    // Two incommensurate, direction-rotated sine octaves per field, with
    // dominant wavelengths of ~250-900 blocks: each field traverses several
    // cycles across the 512-block map, so every world gets coherent patches
    // of all five biomes (~60-150 block scale).
    // portableSin (not Math.sin): the biome field feeds terrain generation, so
    // it must be bit-identical across JS engines — see lib/world/noise.ts.
    const s = this.seed * 0.007;
    const temp = portableSin(x * 0.013 + z * 0.006 + s * 1.3) * 0.6 + portableSin(x * 0.029 - z * 0.017 + s * 2.4) * 0.4;
    const moisture = portableSin(x * 0.007 - z * 0.012 + s * 0.8) * 0.6 + portableSin(x * 0.019 + z * 0.023 - s * 1.6) * 0.4;
    const continental = portableSin(x * 0.008 + z * 0.01 + s * 2.1) * 0.55 + portableSin(x * 0.014 - z * 0.009 - s * 1.7) * 0.45;
    const ridge = portableSin(x * 0.024 + z * 0.02 + s) * 0.5 + portableSin(x * 0.016 - z * 0.024 - s) * 0.5;

    if (continental < -0.52) return BiomeId.Ocean;
    if ((continental > 0.5 && ridge > 0) || ridge > 0.8) return BiomeId.Mountains;
    if (temp > 0.2 && moisture < -0.12) return BiomeId.Desert;
    if (moisture > 0.18) return BiomeId.Forest;
    return BiomeId.Plains;
  }
}

