 * respawn point. All added fields are optional so the v2→v3 migration is a pure
 * version bump and pre-v3 saves load with sensible defaults.
 */
export type SaveDataV3 = Omit<SaveDataV2, "version"> & {
  version: 3;
  dayClock?: number;
  hearts?: number;
  hunger?: number;
  spawnPoint?: { x: number; y: number; z: number } | null;
};

/**
 * v4 save shape: v3 plus chest contents as block-entities. The field is
 * optional so the v3→v4 migration is a pure version bump and pre-v4 saves load
 * with no containers.
 */
---
  hunger?: number;
  effects?: SavedEffect[];
  xp?: number;
  stats?: SavedStat[];
  advancements?: string[];
  spawnPoint?: { x: number; y: number; z: number } | null;
  dimension?: DimensionId;
  portalArrival?: { x: number; y: number; z: number };
};

/**
 * Save shape (v17): the players map. Every per-player field moves off
 * the top level into `players[]` (world-level fields — seed, changes,
 * difficulty, hardcore, blockEntities, mobs, vehicles, dayClock — stay put).
 * migrateSaveV16toV17 wraps a flat single-player save as [{ id: "local", … }]
 * and rewrites pet owners from the legacy literal "player" to "local".
 */
export type SaveDataV17 = Omit<
  SaveDataV16,
  | "version"
  | "gameMode"
  | "gameOver"
  | "inventorySlots"
  | "equippedArmor"
  | "selectedSlot"
  | "player"
  | "hearts"
  | "hunger"
  | "spawnPoint"
  | "effects"
  | "xp"
  | "stats"
  | "advancements"
> & {
  version: 17;
  players: SavedPlayer[];
---
}

/** Restores the permadeath game-over flag — only ever true on a hardcore save, so a stray flag on a non-hardcore (corrupt) save can't lock it into spectator. */
export function restoreGameOver(save: Pick<SaveData, "hardcore">, saved: SavedPlayer): boolean {
  return save.hardcore === true && saved.gameOver === true;
}

/** Restores the bed respawn point; null if absent or explicitly cleared. */
export function restoreSpawnPoint(save: SavedPlayer): { x: number; y: number; z: number } | null {
  const sp = save.spawnPoint;
  if (!sp || !Number.isFinite(sp.x) || !Number.isFinite(sp.y) || !Number.isFinite(sp.z)) return null;
  return { x: Math.floor(sp.x), y: Math.floor(sp.y), z: Math.floor(sp.z) };
}

/**
 * Restores the player's position; null when absent or non-finite. A corrupt save
 * with NaN/Infinity coords would otherwise load a broken world — and slip past the
 * `position.y < 2` unstuck net, since any comparison with NaN is false. Coords stay
 * floats (the player isn't grid-aligned), unlike the floored spawn point.
 */
export function restorePlayerPosition(save: SavedPlayer): { x: number; y: number; z: number } | null {
---
    gameOver,
    inventorySlots,
    equippedArmor,
    selectedSlot,
    player,
    hearts,
    hunger,
    spawnPoint,
    effects,
    xp,
    stats,
    advancements,
    mobs,
    ...world
  } = save;
  return {
    ...world,
    version: 17,
    mobs: mobs?.map((mob) => (mob.owner === "player" ? { ...mob, owner: "local" } : mob)),
    players: [
      {
        id: "local",
        position: player,
        inventorySlots,
        equippedArmor,
        selectedSlot,
        gameMode,
        gameOver,
        hearts,
        hunger,
        effects,
        xp,
        stats,
        advancements,
        spawnPoint
      }
    ]
  };
}

/**
---
  "oxygen",
  "effects",
  "xp",
  "stats",
  "advancements",
  "isDead",
  "respawnTimer",
  "spawnPoint",
  "mining",
  "fishing",
  "mountedVehicleId",
  "inventoryOpen",
  "advancementsOpen",
  "craftingStation",
  "activeVillagerProfession",
