2	 * Soak load: drives N synthetic clients into one room and reports the server's
3	 * tick budget and bandwidth so MAX_ROOMS and the deadbands can be tuned from
4	 * numbers, not guesses:
5	 *
6	 *   GAME_TICKET_SECRET=… ADMIN_TOKEN=… \
7	 *     bun scripts/loadSim.ts ws://localhost:8080 my-world 8 30
8	 *                            └ url            └ world └ clients └ seconds
9	 *
10	 * Each client joins, streams a 20 Hz pose walking a small circle plus an
11	 * occasional block break, and tallies bytes received. Meanwhile it polls the
12	 * admin /rooms endpoint (ADMIN_TOKEN) once a second for the server's own
13	 * players/tick/slowest-tick/bandwidth counters, then prints per-client and
14	 * server-side p95 tick time and aggregate throughput.
15	 */
16	import { PROTOCOL_VERSION } from "@/lib/net/protocol";
17	import { signTicket } from "@/lib/net/tickets";
18	
19	const [, , urlArg, worldArg, clientsArg, secondsArg] = process.argv;
20	const wsUrl = urlArg ?? "ws://localhost:8080";
21	const httpUrl = wsUrl.replace(/^ws/, "http");
22	const worldId = worldArg ?? "loadsim-world";
23	const clientCount = Math.max(1, Number.parseInt(clientsArg ?? "8", 10));
24	const durationMs = Math.max(1, Number.parseInt(secondsArg ?? "30", 10)) * 1000;
25	
26	const secret = process.env.GAME_TICKET_SECRET;
27	if (!secret) {
28	  console.error("GAME_TICKET_SECRET required (must match the server)");
29	  process.exit(1);
30	}
31	const adminToken = process.env.ADMIN_TOKEN;
32	
33	type ClientStat = { id: string; bytesIn: number; frames: number; connected: boolean };
34	
35	async function spawnClient(index: number): Promise<ClientStat> {
36	  const stat: ClientStat = { id: `sim-${index}`, bytesIn: 0, frames: 0, connected: false };
37	  const ticket = await signTicket(
38	    { sub: stat.id, wid: worldId, name: `Sim${index}`, skinId: null, role: index === 0 ? "owner" : "member", pv: PROTOCOL_VERSION },
39	    secret!
40	  );
41	  const ws = new WebSocket(`${wsUrl}/ws`);
42	  ws.binaryType = "arraybuffer";
43	
44	  let seq = 0;
45	  const center = { x: 256, y: 80, z: 256 };
46	  const phase = (index / clientCount) * Math.PI * 2;
47	
48	  ws.onopen = () => ws.send(JSON.stringify({ t: "hello", ticket, protocol: PROTOCOL_VERSION }));
49	  ws.onmessage = (event) => {
50	    stat.frames += 1;
51	    stat.bytesIn += typeof event.data === "string" ? event.data.length : (event.data as ArrayBuffer).byteLength;
52	    if (typeof event.data === "string") {
53	      const message = JSON.parse(event.data) as { t: string };
54	      if (message.t === "welcome") stat.connected = true;
55	    }
56	  };
57	  ws.onclose = () => {
58	    stat.connected = false;
59	  };
60	
61	  const move = { forward: true, back: false, left: false, right: false, jump: false, sprint: false, crouch: false };
62	  const poser = setInterval(() => {
63	    if (ws.readyState !== WebSocket.OPEN) return;
64	    seq += 1;
65	    const t = seq / 20;
66	    const x = center.x + Math.cos(t + phase) * 6;
67	    const z = center.z + Math.sin(t + phase) * 6;
68	    ws.send(JSON.stringify({ t: "pose", seq, d: "overworld", x, y: center.y, z, yaw: t, pitch: 0, onGround: true, move, mineHeld: seq % 40 < 10 }));
69	    if (seq % 20 === 0) ws.send(JSON.stringify({ t: "ping", id: seq, tMs: Date.now() }));
70	    // A block break every ~3s so the edit/journal path is exercised under load.
71	    if (seq % 60 === 0)
72	      ws.send(JSON.stringify({ t: "cmd", seq, d: "overworld", cmd: { type: "attack" }, pose: { x, y: center.y + 1.6, z, yaw: t, pitch: -1.4 } }));
73	  }, 50);
74	
75	  setTimeout(() => {
76	    clearInterval(poser);
77	    try {
78	      ws.close();
79	    } catch {
80	      /* already closed */
81	    }
82	  }, durationMs);
83	  return stat;
84	}
85	
86	async function pollRooms(): Promise<{ players: number; tick: number; slowestTickMs: number; kbOutPerSec: number } | null> {
87	  if (!adminToken) return null;
88	  try {
89	    const response = await fetch(`${httpUrl}/rooms`, { headers: { authorization: `Bearer ${adminToken}` } });
90	    if (!response.ok) return null;
91	    const body = (await response.json()) as { rooms: Array<{ worldId: string; players: number; tick: number; slowestTickMs: number; kbOutPerSec: number }> };
92	    return body.rooms.find((r) => r.worldId === worldId) ?? null;
93	  } catch {
94	    return null;
95	  }
96	}
