98	console.log(`loadSim: ${clientCount} clients → ${worldId} for ${durationMs / 1000}s`);
99	const stats = await Promise.all(Array.from({ length: clientCount }, (_, i) => spawnClient(i)));
100	
101	const slowestSamples: number[] = [];
102	let peakKbOut = 0;
103	const sampler = setInterval(async () => {
104	  const room = await pollRooms();
105	  if (!room) return;
106	  slowestSamples.push(room.slowestTickMs);
107	  peakKbOut = Math.max(peakKbOut, room.kbOutPerSec);
108	  console.log(`  t=${(room.tick / 20).toFixed(0)}s players=${room.players} slowestTick=${room.slowestTickMs}ms out=${room.kbOutPerSec}KB/s`);
109	}, 1000);
110	
111	await new Promise((resolve) => setTimeout(resolve, durationMs + 500));
112	clearInterval(sampler);
113	
114	const connected = stats.filter((s) => s.connected || s.frames > 0).length;
115	const totalKbIn = stats.reduce((sum, s) => sum + s.bytesIn, 0) / 1024;
116	const p95 = slowestSamples.length
117	  ? [...slowestSamples].sort((a, b) => a - b)[Math.min(slowestSamples.length - 1, Math.floor(slowestSamples.length * 0.95))]
118	  : null;
119	
120	console.log(`\n── results ──`);
121	console.log(`clients that joined: ${connected}/${clientCount}`);
122	console.log(`downstream received: ${totalKbIn.toFixed(0)} KB total, ${(totalKbIn / (durationMs / 1000)).toFixed(1)} KB/s aggregate`);
123	if (p95 !== null) console.log(`server tick p95: ${p95}ms (budget is 50ms); peak downstream: ${peakKbOut} KB/s`);
124	else console.log(`(set ADMIN_TOKEN to sample server-side tick/bandwidth stats)`);
125	process.exit(0);

