6	/**
7	 * The client↔game-server wire protocol. Versioned as a whole: a client built
8	 * against a different PROTOCOL_VERSION is refused at the door (its join
9	 * ticket carries the number), so mid-session format drift can't happen.
10	 *
11	 * v1 is JSON envelopes discriminated on `t`, except the one big payload —
12	 * the join world-sync — which travels as a gzipped binary frame (see
13	 * codec.ts). The envelope layout deliberately leaves room to move the hot
14	 * paths (pose/tick) to packed binary later without renegotiating anything.
15	 *
16	 * v4 puts the DIMENSION on the wire: every pose/cmd is stamped with the
17	 * sender's dimension (`d` — the travel race guard: the server drops frames
18	 * from the world the sender just left), the welcome/worldSync/roster carry
19	 * where each player is, and `dim`/`playerDim` drive server-initiated
20	 * dimension travel. Poses and tick contents are otherwise coordinates in ONE
21	 * dimension's voxel space — the recipient's — so everything else is
22	 * unchanged.
23	 *
24	 * Validation is hand-rolled and TOTAL (the save.ts house style): the server
25	 * feeds hostile bytes through these readers and gets a typed message or
26	 * null — never an exception, never a partially-checked object.
27	 */
28	export const PROTOCOL_VERSION = 4;
29	
30	// ── close codes (WebSocket application range) ────────────────────────────────
31	export const CLOSE_BAD_TICKET = 4000;
32	export const CLOSE_PROTOCOL_MISMATCH = 4001;
33	export const CLOSE_ROOM_FULL = 4002;
34	export const CLOSE_KICKED = 4003;
