44	 * a fatal close walks this once — five tries over ~23 s — before the client
45	 * gives up and shows the disconnect modal.
46	 */
47	export const RECONNECT_DELAYS_MS = [1000, 2000, 4000, 8000, 8000] as const;
48	
49	// ── client → server ──────────────────────────────────────────────────────────
50	
51	/** First frame on the socket: the join ticket (minted by the web API) + the client's protocol. */
52	export type HelloMessage = { t: "hello"; ticket: string; protocol: number };
53	
54	/** The client-authoritative avatar pose, streamed at tick rate. */
55	export type PoseMessage = {
56	  t: "pose";
57	  seq: number;
58	  /** The dimension the sender believes it is in — the server silently drops a mismatch (frames in flight across a travel swap). */
59	  d: DimensionId;
