94	export type ResyncMessage = { t: "resync" };
95	/** Owner-only: eject a player from the world. Ignored from a non-owner (server re-checks the ticket role). */
96	export type KickMessage = { t: "kick"; targetId: string };
97	
98	export type ClientMessage = HelloMessage | PoseMessage | CmdMessage | ChatMessage | PingMessage | ResyncMessage | KickMessage;
