38	/**
39	 * One world room: an authoritative GameEngine on the fixed 20 Hz ticker,
40	 * fed by client poses/commands and broadcasting per-tick deltas. Sockets are
41	 * abstracted as ClientSink so the whole class unit-tests with fakes; only
42	 * index.ts binds it to real Bun WebSockets.
43	 */
44	
45	export type ClientSink = {
46	  send(data: string | Uint8Array): void;
47	  close(code: number, reason?: string): void;
48	  bufferedAmount(): number;
49	};
50	
51	type ClientConn = {
52	  playerId: string;
53	  name: string;
54	  skinId: string | null;
55	  role: "owner" | "member";
56	  sink: ClientSink;
57	  /** Highest pose seq applied (stale/replayed packets drop). */
58	  poseSeq: number;
59	  /** Tick of the last accepted pose (drives the clamp's elapsed time). */
60	  lastPoseTick: number;
61	  /** Per-second message budgets (reset each second-boundary tick). */
62	  budget: { cmd: number; chat: number; attack: number };
63	  /** Sustained-backpressure strikes toward a slow-client kick. */
64	  slowStrikes: number;
65	  /** Shadow of the last self-delta sent (reference/primitive compares). */
66	  shadow: {
67	    inventory: unknown;
68	    equippedArmor: unknown;
69	    selectedSlot: number;
70	    hearts: number;
71	    hunger: number;
72	    oxygen: number;
73	    xp: number;
74	    isDead: boolean;
75	    respawnSeconds: number;
76	    gameMode: string;
77	    sleeping: boolean;
78	    effectsKey: string;
79	    mountedVehicleId: number | null;
80	    advancementsSize: number;
81	    statsSig: string;
82	  } | null;
83	};
84	
85	/**
86	 * Stats the client accrues on its own (recordTick runs on the replica), so they
87	 * never travel in the SelfDelta — only the event-driven counters the replica
88	 * can't derive (kills, blocks mined, crafts) sync.
89	 */
90	const CLIENT_LOCAL_STATS = new Set(["play_time", "distance_walked"]);
91	
92	const PERSIST_INTERVAL_TICKS = 20 * 60; // 60s
93	const KEYFRAME_INTERVAL_TICKS = 20 * 5; // 5s
94	const DAY_INTERVAL_TICKS = 20; // 1s
95	const POSE_CHECKPOINT_TICKS = 20; // 1s — log pose anchors between commands
96	const MOB_DEADBAND_SQ = 0.05 * 0.05;
97	const BACKPRESSURE_SOFT_BYTES = 256 * 1024;
98	const BACKPRESSURE_KICK_BYTES = 1024 * 1024;
99	const BACKPRESSURE_KICK_STRIKES = 100; // ~5s of sustained >1MB at 20Hz
100	const DEFAULT_COMMAND_LOG_SIZE = 4096;
101	/**
102	 * Per-second cap on attack commands per client. Far above honest clicking,
103	 * but with lag-compensated rewind an unbounded rate would let a scripted
104	 * client sweep a mob's whole 900 ms position trail with varied view stamps.
105	 */
106	const MELEE_ATTACKS_PER_SECOND = 12;
107	
108	/**
109	 * One entry in a room's replay log: a dispatched command (with its claimed eye
110	 * pose, plus the v3 view stamp when present) or a periodic pose anchor. Replay
111	 * ignores `view` — attack-replay fidelity was already approximate (1 s pose
112	 * anchors); it's recorded for offline diagnosis of rewind disputes.
113	 */
114	export type CommandLogEntry =
115	  | { tick: number; playerId: string; cmd: Command; pose: { x: number; y: number; z: number; yaw: number; pitch: number }; view?: number }
116	  | { tick: number; playerId: string; pose: { x: number; y: number; z: number; yaw: number; pitch: number } };
117	
118	/** A room's replay log plus the world constants needed to reconstruct it offline (see server/scripts/replay.ts). */
119	export type RoomLogDump = {
120	  worldId: string;
121	  seed: number;
122	  worldType: string;
123	  difficulty: string;
124	  hardcore: boolean;
125	  tick: number;
126	  entries: CommandLogEntry[];
127	};
