129	export class Room {
130	  readonly worldId: string;
131	  readonly engine: GameEngine;
132	  private readonly clients = new Map<string, ClientConn>();
133	  /** Persisted slices of players who left (merged into the stored save). */
134	  private readonly offlinePlayers = new Map<string, SavedPlayer>();
135	  private readonly persistence: Persistence;
136	  private ticker: FixedTicker | null = null;
137	  private tickCount = 0;
138	  private dirtySinceStore = false;
139	  private readonly mobShadow = new Map<number, { x: number; y: number; z: number; hp: number }>();
140	  /** Per-tick mob positions for melee lag compensation (see handleMessage "cmd"). */
141	  private readonly mobHistory = createMobPoseHistory();
142	  private readonly vehicleShadow = new Map<number, { x: number; y: number; z: number; yaw: number; riderId: string | null }>();
143	  /** Count of live arrows broadcast last tick — drives one trailing empty `prj` frame so the client prunes the last one. */
144	  private lastProjectileCount = 0;
145	  /** Wall-clock ms when the room became empty (idle-eviction clock), or null while occupied. */
146	  emptySinceMs: number | null;
147	  /** p95-ish diagnostics: the slowest tick of the last window. */
148	  private slowestTickMs = 0;
149	  /**
150	   * Total bytes sent downstream (monotonic); diagnostics reports the delta
151	   * since its last read. Counts PRE-compression payload sizes — Bun exposes
152	   * no per-send compressed size, so with permessage-deflate negotiated the
153	   * real wire usage is smaller than `kbOutPerSec` suggests (documented in
154	   * tuning.md; check Fly egress metrics for wire-accurate numbers).
155	   */
156	  private bytesOut = 0;
157	  private lastDiagBytes = 0;
158	  private lastDiagTick = 0;
159	  /** Rolling replay log: recent commands + pose anchors (ring-bounded). */
160	  private readonly commandLog: CommandLogEntry[] = [];
161	  private readonly commandLogSize: number;
162	
163	  constructor(
164	    record: WorldRecord,
165	    persistence: Persistence,
166	    private readonly now: () => number = () => Date.now(),
167	    commandLogSize = Number.parseInt(process.env.COMMAND_LOG_SIZE ?? "", 10) || DEFAULT_COMMAND_LOG_SIZE
168	  ) {
169	    this.worldId = record.id;
170	    this.persistence = persistence;
171	    this.commandLogSize = commandLogSize;
172	    this.engine = new GameEngine({
173	      save: record.save,
174	      seed: record.seed,
175	      worldType: record.worldType as never,
176	      difficulty: record.difficulty as never,
177	      hardcore: record.hardcore,
178	      authority: "server",
179	      headless: true,
180	      bootPlayer: false
181	    });
182	    for (const saved of record.save?.players ?? []) this.offlinePlayers.set(saved.id, saved);
183	    this.emptySinceMs = this.now();
184	  }
185	
186	  /** Starts the 20 Hz ticker (index.ts calls this once after construction). */
187	  start(setTimer?: (fn: () => void, ms: number) => ReturnType<typeof setTimeout>, clearTimer?: (id: ReturnType<typeof setTimeout>) => void): void {
188	    this.ticker = createFixedTicker({
189	      onTick: (dt) => this.tick(dt),
190	      now: () => this.now(),
191	      ...(setTimer ? { setTimer } : {}),
192	      ...(clearTimer ? { clearTimer } : {})
193	    });
194	  }
195	
196	  playerCount(): number {
197	    return this.clients.size;
198	  }
199	
200	  diagnostics(): { worldId: string; players: number; tick: number; slowestTickMs: number; kbOutPerSec: number } {
201	    // Bandwidth over the window since the last read (not a lifetime average).
202	    const windowTicks = Math.max(1, this.tickCount - this.lastDiagTick);
203	    const windowBytes = this.bytesOut - this.lastDiagBytes;
204	    this.lastDiagTick = this.tickCount;
205	    this.lastDiagBytes = this.bytesOut;
206	    return {
207	      worldId: this.worldId,
208	      players: this.clients.size,
209	      tick: this.tickCount,
210	      slowestTickMs: Math.round(this.slowestTickMs * 100) / 100,
211	      kbOutPerSec: Math.round((windowBytes / 1024 / (windowTicks * TICK_SECONDS)) * 10) / 10
212	    };
213	  }
214	
215	  /** The replay log + world constants (admin-only; drives server/scripts/replay.ts). */
216	  logDump(): RoomLogDump {
217	    return {
218	      worldId: this.worldId,
219	      seed: this.engine.state.world.seed,
220	      worldType: this.engine.worldTypeName,
221	      difficulty: this.engine.state.difficulty,
222	      hardcore: this.engine.state.hardcore,
223	      tick: this.tickCount,
224	      entries: [...this.commandLog]
225	    };
226	  }
227	
228	  private recordLog(entry: CommandLogEntry): void {
229	    this.commandLog.push(entry);
230	    if (this.commandLog.length > this.commandLogSize) this.commandLog.splice(0, this.commandLog.length - this.commandLogSize);
231	  }
232	
233	  /** Admits a verified ticket onto a socket: joins the engine and syncs the world. */
234	  async join(claims: TicketClaims, sink: ClientSink): Promise<boolean> {
235	    // A reconnecting member already owns a slot — only a genuinely NEW player
236	    // counts against capacity, so a dropped socket can always come back.
237	    const reconnecting = this.clients.has(claims.sub);
238	    if (!reconnecting && this.clients.size >= ROOM_CAPACITY) {
239	      sink.close(CLOSE_ROOM_FULL, "room full");
240	      return false;
241	    }
242	    // A reconnect replaces the old socket (the stale one is closed silently).
243	    this.clients.get(claims.sub)?.sink.close(CLOSE_KICKED, "replaced by a new connection");
244	    this.clients.delete(claims.sub);
245	
246	    const restore = this.offlinePlayers.get(claims.sub) ?? null;
247	    const player = this.engine.addPlayer({ id: claims.sub, restore });
248	    this.offlinePlayers.delete(claims.sub);
249	    this.dirtySinceStore = true;
250	
251	    const conn: ClientConn = {
252	      playerId: claims.sub,
253	      name: claims.name,
254	      skinId: claims.skinId,
255	      role: claims.role,
256	      sink,
257	      poseSeq: -1,
258	      lastPoseTick: this.tickCount,
259	      budget: { cmd: 0, chat: 0, attack: 0 },
260	      slowStrikes: 0,
261	      shadow: null
262	    };
263	    this.clients.set(claims.sub, conn);
264	    this.emptySinceMs = null;
265	
266	    sink.send(
267	      encodeServerMessage({
268	        t: "welcome",
269	        protocol: PROTOCOL_VERSION,
270	        playerId: claims.sub,
271	        worldId: this.worldId,
272	        seed: this.engine.state.world.seed,
273	        worldType: this.engine.worldTypeName,
274	        difficulty: this.engine.state.difficulty,
275	        hardcore: this.engine.state.hardcore,
276	        dayClock: this.engine.state.dayClock,
277	        tick: this.tickCount,
278	        role: claims.role,
279	        dimension: this.engine.state.dimension,
280	        players: this.roster()
281	      })
282	    );
283	    sink.send(await gzipWorldSync(this.buildWorldSync()));
284	    this.broadcast({ t: "playerJoined", player: this.rosterEntry(player, conn) }, claims.sub);
285	    return true;
286	  }
287	
288	  /** Owner-initiated eject: close the socket with a fatal code so the client won't retry, then leave. Returns false if not present. */
289	  kick(playerId: string): boolean {
290	    const conn = this.clients.get(playerId);
291	    if (!conn) return false;
292	    conn.sink.close(CLOSE_KICKED, "removed by the world owner");
293	    this.leave(playerId);
294	    return true;
295	  }
296	
297	  /** Removes a player (socket closed or kicked); persists their slice into the offline set. */
298	  leave(playerId: string): void {
299	    const conn = this.clients.get(playerId);
300	    if (!conn) return;
301	    this.clients.delete(playerId);
302	    const saved = this.engine.removePlayer(playerId);
303	    if (saved) this.offlinePlayers.set(playerId, saved);
304	    this.dirtySinceStore = true;
305	    this.broadcast({ t: "playerLeft", id: playerId });
306	    if (this.clients.size === 0) this.emptySinceMs = this.now();
307	  }
308	
309	  /** One validated client frame. */
310	  async handleMessage(playerId: string, message: ClientMessage): Promise<void> {
311	    const conn = this.clients.get(playerId);
312	    if (!conn) return;
313	    switch (message.t) {
314	      case "pose": {
315	        if (message.seq <= conn.poseSeq) return; // stale or replayed
316	        conn.poseSeq = message.seq;
317	        const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
318	        const { accepted } = this.engine.applyRemotePose(playerId, message, elapsed);
319	        this.engine.setPlayerInput(playerId, { move: message.move, mineHeld: message.mineHeld });
320	        if (accepted) {
321	          conn.lastPoseTick = this.tickCount;
322	        } else {
323	          const player = this.engine.state.players.get(playerId);
324	          // A mounted player's position is server-owned and streamed via the
325	          // self-delta; don't fight that with forcePose (the reject there is
326	          // "ignore the stream", not "you desynced"). Only correct real desync.
327	          if (player && player.mountedVehicleId === null) {
328	            conn.sink.send(
329	              encodeServerMessage({
330	                t: "forcePose",
331	                x: player.position.x,
332	                y: player.position.y,
333	                z: player.position.z,
334	                yaw: player.yaw,
335	                pitch: player.pitch
336	              })
337	            );
338	          }
339	        }
340	        return;
341	      }
342	      case "cmd": {
343	        if (conn.budget.cmd >= 60) return; // per-second flood guard
344	        conn.budget.cmd += 1;
345	        if (message.cmd.type === "attack") {
346	          if (conn.budget.attack >= MELEE_ATTACKS_PER_SECOND) return;
347	          conn.budget.attack += 1;
348	        }
349	        // Room-wide settings are the owner's call, not any member's.
350	        if ((message.cmd.type === "setDifficulty" || message.cmd.type === "setGameMode") && conn.role !== "owner") return;
351	        // Apply the claimed pose (same clamps as the stream) so the command's
352	        // raycast happens from where the client actually stood/aimed.
353	        const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
354	        const { accepted } = this.engine.applyRemotePose(
355	          playerId,
356	          { ...message.pose, onGround: this.engine.state.players.get(playerId)?.onGround ?? false },
357	          elapsed
358	        );
359	        // Advance the pose clock on an accepted cmd pose too — otherwise a
360	        // client sending only cmds lets `elapsed` grow and inflate the clamp.
361	        if (accepted) conn.lastPoseTick = this.tickCount;
362	        this.recordLog({ tick: this.tickCount, playerId, cmd: message.cmd, pose: message.pose, ...(message.view !== undefined ? { view: message.view } : {}) });
363	        // Melee lag compensation: a stamped attack rewinds TARGET SELECTION to
364	        // the tick the attacker was rendering, clamped into the rewind window.
365	        // Everything degrades to live behavior: unstamped/future/too-stale
366	        // stamps, mobs without history (spawned since), non-attack commands.
367	        let opts: DispatchOptions | undefined;
368	        if (message.cmd.type === "attack" && message.view !== undefined) {
369	          const viewTick = Math.round(message.view / (TICK_SECONDS * 1000));
370	          const rewindTick = Math.min(this.tickCount, Math.max(viewTick, this.tickCount - MELEE_REWIND_MAX_TICKS));
371	          if (rewindTick < this.tickCount) {
372	            opts = { mobPosOf: (mob) => this.mobHistory.positionAt(rewindTick, mob.id) ?? mob.position };
373	          }
374	        }
375	        this.engine.dispatch(message.cmd, playerId, opts);
376	        return;
377	      }
378	      case "chat": {
379	        if (conn.budget.chat >= 3) return;
380	        conn.budget.chat += 1;
381	        this.broadcast({ t: "chat", from: playerId, name: conn.name, text: message.text });
382	        return;
383	      }
384	      case "ping": {
385	        conn.sink.send(encodeServerMessage({ t: "pong", id: message.id, tMs: message.tMs, serverTick: this.tickCount }));
386	        return;
387	      }
388	      case "resync": {
389	        conn.sink.send(await gzipWorldSync(this.buildWorldSync()));
390	        conn.shadow = null; // resend the full self-delta next tick
391	        return;
392	      }
393	      case "kick": {
394	        // Owner-only, re-checked against the signed ticket role (same gate as the
395	        // owner-wide settings). Can't kick yourself; kick() no-ops on a stranger.
396	        if (conn.role !== "owner" || message.targetId === playerId) return;
397	        this.kick(message.targetId);
398	        return;
399	      }
400	      case "hello":
401	        return; // already admitted; ignore
402	    }
403	  }
404	
405	  /** Drains the room for shutdown: persist + close every socket. */
406	  async shutdown(): Promise<void> {
407	    this.ticker?.stop();
408	    for (const conn of this.clients.values()) conn.sink.close(CLOSE_SERVER_SHUTDOWN, "server restarting");
409	    for (const playerId of [...this.clients.keys()]) this.leave(playerId);
410	    await this.persist();
411	  }
412	
413	  /** Persists the full world (live players merged with offline slices). */
414	  async persist(): Promise<void> {
415	    const save = this.engine.serialize();
416	    for (const [id, saved] of this.offlinePlayers) {
417	      if (!save.players.some((p) => p.id === id)) save.players.push(saved);
418	    }
419	    const bun = Bun as unknown as { gzipSync(d: Uint8Array): Uint8Array };
420	    const blob = bun.gzipSync(new TextEncoder().encode(JSON.stringify(save)));
421	    await this.persistence.storeWorld(this.worldId, blob, save.version);
422	    this.dirtySinceStore = false;
423	  }
424	
425	  // ── internals ──────────────────────────────────────────────────────────────
426	
427	  private tick(dt: number): void {
428	    const started = this.now();
429	    this.tickCount += 1;
430	    if (this.tickCount % 20 === 0) {
431	      for (const conn of this.clients.values()) conn.budget = { cmd: 0, chat: 0, attack: 0 };
432	    }
433	
434	    this.engine.step(dt);
435	    // Post-step positions: exactly what this tick's mp/keyframe broadcasts,
436	    // i.e. the timeline the client's interpolation buffers (and view stamps)
437	    // live on.
438	    this.mobHistory.record(this.tickCount, this.engine.state.mobs);
439	    const events = this.engine.consumeEvents();
440	    const blocks = this.engine.state.blockChanges.drainEdits();
441	    if (events.some((e) => e.type === "blockPlaced" || e.type === "blockBroken" || e.type === "explosion")) this.dirtySinceStore = true;
442	
443	    const mobPoses = this.collectMobPoses(false);
444	    const vehiclePoses = this.collectVehiclePoses(false);
445	    const projectilePoses = this.collectProjectilePoses();
446	    // Send a trailing empty `prj` the tick the last arrow clears so clients prune it.
447	    const includeProjectiles = projectilePoses.length > 0 || this.lastProjectileCount > 0;
448	    this.lastProjectileCount = projectilePoses.length;
449	    const day = this.tickCount % DAY_INTERVAL_TICKS === 0 ? this.engine.state.dayClock : undefined;
450	
451	    for (const conn of this.clients.values()) {
452	      const buffered = conn.sink.bufferedAmount();
453	      if (buffered > BACKPRESSURE_KICK_BYTES) {
454	        conn.slowStrikes += 1;
455	        if (conn.slowStrikes > BACKPRESSURE_KICK_STRIKES) {
456	          conn.sink.close(CLOSE_SLOW_CLIENT, "client cannot keep up");
457	          this.leave(conn.playerId);
458	        }
459	        continue;
460	      }
461	      conn.slowStrikes = 0;
462	      const shed = buffered > BACKPRESSURE_SOFT_BYTES;
463	      const message: TickMessage = {
464	        t: "tick",
465	        n: this.tickCount,
466	        ...(blocks.length > 0 ? { blocks } : {}),
467	        ev: events,
468	        pp: shed ? [] : this.collectPlayerPoses(conn.playerId),
469	        mp: shed ? [] : mobPoses,
470	        ...(!shed && vehiclePoses.length > 0 ? { vp: vehiclePoses } : {}),
471	        ...(!shed && includeProjectiles ? { prj: projectilePoses } : {}),
472	        ...(day !== undefined ? { day } : {}),
473	        ...(this.buildSelfDelta(conn) ?? {})
474	      };
475	      const encoded = encodeServerMessage(message);
476	      this.bytesOut += encoded.length;
477	      conn.sink.send(encoded);
478	    }
479	
480	    // Pose anchors between commands keep an offline replay's positions aligned.
481	    if (this.tickCount % POSE_CHECKPOINT_TICKS === 0) {
482	      for (const player of this.engine.state.players.values()) {
483	        this.recordLog({
484	          tick: this.tickCount,
485	          playerId: player.id,
486	          pose: { x: player.position.x, y: player.position.y, z: player.position.z, yaw: player.yaw, pitch: player.pitch }
487	        });
488	      }
489	    }
490	
491	    if (this.tickCount % KEYFRAME_INTERVAL_TICKS === 0 && this.clients.size > 0) {
492	      this.broadcast({ t: "mobsKeyframe", n: this.tickCount, mobs: this.collectMobPoses(true) });
493	    }
494	    if (this.tickCount % PERSIST_INTERVAL_TICKS === 0 && this.dirtySinceStore) {
495	      void this.persist();
496	    }
497	    this.slowestTickMs = Math.max(this.slowestTickMs * 0.99, this.now() - started);
498	  }
499	
500	  private roster(): RosterEntry[] {
501	    const out: RosterEntry[] = [];
502	    for (const conn of this.clients.values()) {
503	      const player = this.engine.state.players.get(conn.playerId);
504	      if (player) out.push(this.rosterEntry(player, conn));
505	    }
506	    return out;
507	  }
508	
509	  private rosterEntry(player: PlayerState, conn: ClientConn): RosterEntry {
510	    return {
511	      id: player.id,
512	      name: conn.name,
513	      skinId: conn.skinId,
514	      dim: this.engine.state.dimension,
515	      x: qPos(player.position.x),
516	      y: qPos(player.position.y),
517	      z: qPos(player.position.z),
518	      yaw: qAng(player.yaw)
519	    };
520	  }
521	
522	  private buildWorldSync(): WorldSync {
523	    const state = this.engine.state;
524	    return {
525	      t: "worldSync",
526	      tick: this.tickCount,
527	      dimension: state.dimension,
528	      dayClock: state.dayClock,
529	      changes: state.blockChanges.changes(),
530	      blockEntities: serializeContainers(state.containers),
531	      lootedChests: serializeLootedChests(state.lootedWorldgenChests),
532	      mobs: serializeMobs(state.mobs),
533	      liveMobs: this.collectMobPoses(true),
534	      vehicles: this.collectVehiclePoses(true),
535	      projectiles: this.collectProjectilePoses(),
536	      players: this.roster()
537	    };
538	  }
539	
540	  private collectPlayerPoses(except: string): PlayerPose[] {
541	    const out: PlayerPose[] = [];
542	    for (const player of this.engine.state.players.values()) {
543	      if (player.id === except) continue;
544	      out.push({
545	        id: player.id,
546	        x: qPos(player.position.x),
547	        y: qPos(player.position.y),
548	        z: qPos(player.position.z),
549	        yaw: qAng(player.yaw),
550	        pitch: qAng(player.pitch)
551	      });
552	    }
553	    return out;
554	  }
555	
556	  private collectMobPoses(keyframe: boolean): MobPose[] {
557	    const out: MobPose[] = [];
558	    for (const mob of this.engine.state.mobs) {
559	      const shadow = this.mobShadow.get(mob.id);
560	      const moved =
561	        !shadow ||
562	        (mob.position.x - shadow.x) ** 2 + (mob.position.y - shadow.y) ** 2 + (mob.position.z - shadow.z) ** 2 > MOB_DEADBAND_SQ ||
563	        mob.hp !== shadow.hp;
564	      // Delta frames go at half rate (10 Hz) — keyframes always carry everything.
565	      if (!keyframe && (!moved || this.tickCount % 2 !== 0)) continue;
566	      this.mobShadow.set(mob.id, { x: mob.position.x, y: mob.position.y, z: mob.position.z, hp: mob.hp });
567	      out.push({
568	        id: mob.id,
569	        kind: mob.kind,
570	        hostile: mob.hostile,
571	        x: qPos(mob.position.x),
572	        y: qPos(mob.position.y),
573	        z: qPos(mob.position.z),
574	        yaw: qAng(mob.yaw),
575	        hp: mob.hp,
576	        moveSpeed: mob.moveSpeed
577	      });
578	    }
579	    if (keyframe) {
580	      const alive = new Set(this.engine.state.mobs.map((m) => m.id));
581	      for (const id of this.mobShadow.keys()) if (!alive.has(id)) this.mobShadow.delete(id);
582	    }
583	    return out;
584	  }
585	
586	  /**
587	   * Vehicle poses. `force` (join sync) emits every boat; otherwise only those
588	   * whose position/yaw/rider changed since the last broadcast (deadband — a
589	   * parked raft costs nothing). Vehicles never despawn, so no absence-pruning.
590	   */
591	  private collectVehiclePoses(force: boolean): VehiclePose[] {
592	    const out: VehiclePose[] = [];
593	    for (const vehicle of this.engine.state.vehicles) {
594	      const riderId = vehicle.rider;
595	      const shadow = this.vehicleShadow.get(vehicle.id);
596	      const moved =
597	        !shadow ||
598	        (vehicle.position.x - shadow.x) ** 2 + (vehicle.position.y - shadow.y) ** 2 + (vehicle.position.z - shadow.z) ** 2 > MOB_DEADBAND_SQ ||
599	        vehicle.yaw !== shadow.yaw ||
600	        riderId !== shadow.riderId;
601	      if (!force && !moved) continue;
602	      this.vehicleShadow.set(vehicle.id, { x: vehicle.position.x, y: vehicle.position.y, z: vehicle.position.z, yaw: vehicle.yaw, riderId });
603	      out.push({
604	        id: vehicle.id,
605	        kind: vehicle.kind,
606	        x: qPos(vehicle.position.x),
607	        y: qPos(vehicle.position.y),
608	        z: qPos(vehicle.position.z),
609	        yaw: qAng(vehicle.yaw),
610	        riderId
611	      });
612	    }
613	    return out;
614	  }
615	
616	  /** Every live arrow, full state each tick (they're few and fast — no deadband; the client snaps and prunes by absence). */
617	  private collectProjectilePoses(): ProjectilePose[] {
618	    return this.engine.state.projectiles.map((p) => ({
619	      id: p.id,
620	      x: qPos(p.position.x),
621	      y: qPos(p.position.y),
622	      z: qPos(p.position.z),
623	      // Velocity only orients the client's arrow mesh — position-grade
624	      // precision (2 dp) is ample even for a slow arrow at arc's end.
625	      vx: qPos(p.velocity.x),
626	      vy: qPos(p.velocity.y),
627	      vz: qPos(p.velocity.z)
628	    }));
629	  }
630	
631	  private buildSelfDelta(conn: ClientConn): { self: SelfDelta } | null {
632	    const player = this.engine.state.players.get(conn.playerId);
633	    if (!player) return null;
634	    const effectsKey = JSON.stringify(serializeEffects(player.effects));
635	    const respawnSeconds = Math.ceil(player.respawnTimer);
636	    const eventStats = serializeStats(player.stats).filter((s) => !CLIENT_LOCAL_STATS.has(s.id));
637	    const statsSig = JSON.stringify(eventStats);
638	    const previous = conn.shadow;
639	    const delta: SelfDelta = {};
640	    if (!previous || previous.inventory !== player.inventory) delta.inventorySlots = inventorySlotsSnapshot(player.inventory);
641	    if (!previous || previous.equippedArmor !== player.equippedArmor) delta.equippedArmor = serializeEquippedArmor(player.equippedArmor);
642	    if (!previous || previous.selectedSlot !== player.selectedSlot) delta.selectedSlot = player.selectedSlot;
643	    if (!previous || previous.hearts !== player.hearts) delta.hearts = player.hearts;
644	    if (!previous || previous.hunger !== player.hunger) delta.hunger = player.hunger;
645	    if (!previous || Math.abs(previous.oxygen - player.oxygen) > 0.24) delta.oxygen = player.oxygen;
646	    if (!previous || previous.xp !== player.xp) delta.xp = player.xp;
647	    if (!previous || previous.isDead !== player.isDead) delta.isDead = player.isDead;
648	    if (!previous || previous.respawnSeconds !== respawnSeconds) delta.respawnSeconds = respawnSeconds;
649	    if (!previous || previous.gameMode !== player.gameMode) delta.gameMode = player.gameMode;
650	    if (!previous || previous.sleeping !== player.sleeping) delta.sleeping = player.sleeping;
651	    if (!previous || previous.effectsKey !== effectsKey) delta.effects = serializeEffects(player.effects);
652	    // Advancements grow-only (send the full set on change); event-driven stats sync on change.
653	    if (!previous || previous.advancementsSize !== player.advancements.size) delta.advancements = [...player.advancements];
654	    if (!previous || previous.statsSig !== statsSig) delta.stats = eventStats;
655	    // Mounted: the server owns the rider's position. Announce the mount/dismount
656	    // transition (mountedVehicleId), and carry the authoritative position while
657	    // mounted (and on the dismount tick) so the client snaps rather than predicts.
658	    const mounted = player.mountedVehicleId !== null;
659	    const mountChanged = !previous || previous.mountedVehicleId !== player.mountedVehicleId;
660	    if (mountChanged) delta.mountedVehicleId = player.mountedVehicleId;
661	    if (mounted || mountChanged) {
662	      delta.x = qPos(player.position.x);
663	      delta.y = qPos(player.position.y);
664	      delta.z = qPos(player.position.z);
665	    }
666	    conn.shadow = {
667	      inventory: player.inventory,
668	      equippedArmor: player.equippedArmor,
669	      selectedSlot: player.selectedSlot,
670	      hearts: player.hearts,
671	      hunger: player.hunger,
672	      oxygen: player.oxygen,
673	      xp: player.xp,
674	      isDead: player.isDead,
675	      respawnSeconds,
676	      gameMode: player.gameMode,
677	      sleeping: player.sleeping,
678	      effectsKey,
679	      mountedVehicleId: player.mountedVehicleId,
680	      advancementsSize: player.advancements.size,
681	      statsSig
682	    };
683	    return Object.keys(delta).length > 0 ? { self: delta } : null;
684	  }
685	
686	  private broadcast(message: ServerMessage, except?: string): void {
687	    const encoded = encodeServerMessage(message);
688	    for (const conn of this.clients.values()) {
689	      if (conn.playerId === except) continue;
690	      this.bytesOut += encoded.length;
691	      conn.sink.send(encoded);
692	    }
693	  }
694	}
