        this.leave(conn.playerId);
      }
      continue;
    }
    conn.slowStrikes = 0;
    const shed = buffered > BACKPRESSURE_SOFT_BYTES;
    const data = perShard.get(conn.dimension) ?? perShard.get("overworld")!;
