24	function fakeSink(): ClientSink & { frames: Frame[]; messagesOf<T extends ServerMessage["t"]>(t: T): Array<Extract<ServerMessage, { t: T }>> } {
25	  const frames: Frame[] = [];
26	  return {
27	    frames,
28	    send(data) {
29	      if (typeof data === "string") frames.push({ kind: "text", message: JSON.parse(data) as ServerMessage });
30	      else frames.push({ kind: "binary", sync: gunzipWorldSync(data) });
31	    },
32	    close(code) {
33	      frames.push({ kind: "close", code });
34	    },
35	    bufferedAmount: () => 0,
36	    messagesOf<T extends ServerMessage["t"]>(t: T) {
37	      return frames
38	        .filter((f): f is Extract<Frame, { kind: "text" }> => f.kind === "text")
39	        .map((f) => f.message)
40	        .filter((m): m is Extract<ServerMessage, { t: T }> => m.t === t);
41	    }
42	  };
43	}
