42	 * The engine outlives the socket: a dropped connection (anything but a fatal
43	 * close — a bad ticket, a kick, a slow-client shed) runs a reconnect ladder
44	 * that mints a fresh ticket and redoes the handshake, re-syncing the same
45	 * replica in place — the player sees a brief "reconnecting" badge, not a
46	 * dead world.
47	 */
48	
49	export type NetStatus = "connecting" | "syncing" | "online" | "reconnecting" | "closed";
50	
