144	  const envLatency = Number.parseInt(process.env.NEXT_PUBLIC_NET_SIM_LATENCY_MS ?? "", 10);
145	  const envJitter = Number.parseInt(process.env.NEXT_PUBLIC_NET_SIM_JITTER_MS ?? "", 10);
146	  let simulatedLatencyMs = options.simulatedLatencyMs ?? (Number.isFinite(envLatency) ? envLatency : 0);
147	  let simulatedJitterMs = Number.isFinite(envJitter) ? Math.max(0, envJitter) : 0;
148	
149	  let status: NetStatus = "connecting";
150	  let disposed = false;
151	  let ws: WebSocket | null = null;
152	  const chatListeners = new Set<(entry: { from: string; name: string; text: string }) => void>();
153	  const statusListeners = new Set<(status: NetStatus) => void>();
154	  const rosterListeners = new Set<() => void>();
155	  const setStatus = (next: NetStatus, detail?: string) => {
156	    status = next;
157	    callbacks.onStatus?.(next, detail);
158	    for (const listener of statusListeners) listener(next);
159	  };
160	  const notifyRoster = () => {
161	    for (const listener of rosterListeners) listener();
162	  };
163	
164	  const clock = createClockSync();
165	  const delayCtl = createDelayController();
166	  const ledger = createPredictionLedger();
167	  const pendingEvents: GameEvent[] = [];
168	  const playerBuffers = new Map<string, PoseBuffer>();
169	  const mobBuffers = new Map<number, PoseBuffer>();
170	  const names = new Map<string, string>();
171	  let serverTickTimeMs = 0;
172	
173	  // Client-side traffic counters for the F3 overlay (2 s rolling window).
174	  // Inbound counts post-decompression frame sizes — an approximation when
175	  // permessage-deflate is negotiated, but the right number for "what does the
176	  // client have to process".
177	  const traffic = { inBytes: 0, outBytes: 0, windowStartMs: 0, inKBps: 0, outKBps: 0 };
178	  const rollTrafficWindow = (nowMs: number) => {
179	    if (traffic.windowStartMs === 0) traffic.windowStartMs = nowMs;
180	    const elapsed = nowMs - traffic.windowStartMs;
181	    if (elapsed < 2000) return;
182	    traffic.inKBps = traffic.inBytes / 1024 / (elapsed / 1000);
183	    traffic.outKBps = traffic.outBytes / 1024 / (elapsed / 1000);
184	    traffic.inBytes = 0;
185	    traffic.outBytes = 0;
186	    traffic.windowStartMs = nowMs;
187	  };
