189	  // Latency simulation wraps both directions symmetrically so `ms` reads as a
190	  // one-way delay (round-trip ≈ 2×ms), matching how a player would set it.
191	  // Jitter randomizes each message's delay (Math.random is fine here: net
192	  // tooling, never seed-determined bytes) but delivery stays FIFO — TCP never
193	  // reorders, and the seq/journal handling downstream assumes order. Each
194	  // direction drains through a queued delay line: a monotonic delivery cursor
195	  // makes deadlines non-decreasing, and ONE timer chain delivers in queue
196	  // order. A setTimeout per message would leave ordering to the timer heap's
197	  // tie-breaking, which is not stable for equal deadlines — and the cursor
198	  // clamps bursts to exactly-equal deadlines, so ties are the common case.
199	  const simDelayMs = () => Math.max(0, simulatedLatencyMs + (simulatedJitterMs > 0 ? (Math.random() * 2 - 1) * simulatedJitterMs : 0));
200	  const delayLine = () => {
201	    const queue: Array<{ deliverAt: number; fire: () => void }> = [];
202	    let cursor = 0;
203	    let timer: ReturnType<typeof setTimeout> | null = null;
204	    const drain = () => {
205	      timer = null;
206	      const now = performance.now();
207	      while (queue.length > 0 && queue[0].deliverAt <= now) queue.shift()!.fire();
208	      if (queue.length > 0) timer = setTimeout(drain, Math.max(0, queue[0].deliverAt - now));
209	    };
210	    return {
211	      push(fire: () => void) {
212	        const now = performance.now();
213	        const deliverAt = Math.max(now + simDelayMs(), cursor);
214	        cursor = deliverAt;
215	        queue.push({ deliverAt, fire });
216	        if (timer === null) timer = setTimeout(drain, deliverAt - now);
217	      },
218	      clear() {
219	        if (timer !== null) clearTimeout(timer);
220	        timer = null;
221	        queue.length = 0;
222	      }
223	    };
224	  };
