233	      sendLine.push(() => {
234	        try {
235	          if (socket.readyState === WebSocket.OPEN) socket.send(data);
236	        } catch {
237	          /* socket closed under us */
238	        }
239	      });
240	      return;
241	    }
242	    socket.send(data);
243	  };
