245	  // ── handshake: open a socket, send hello, await welcome ─────────────────────
246	  const handshake = (currentTicket: string, serverUrl: string): Promise<WelcomeMessage> =>
247	    new Promise<WelcomeMessage>((resolve, reject) => {
248	      const socket = makeSocket(`${serverUrl.replace(/\/$/, "")}/ws`);
