275	  const welcome = await handshake(ticket, url);
276	  setStatus("syncing");
277	
278	  // The replica: an empty mirror world generated from the server's seed.
279	  const engine = new GameEngine({
280	    seed: welcome.seed,
281	    worldType: welcome.worldType as never,
282	    difficulty: welcome.difficulty as never,
