338	  const applyRoster = (roster: WelcomeMessage["players"]) => {
339	    for (const entry of roster) upsertRemotePlayer(entry.id, entry.name);
340	    const present = new Set(roster.map((entry) => entry.id));
341	    // Anyone who left while we were away is no longer in the roster.
342	    for (const id of [...state.players.keys()]) {
343	      if (id === playerId || present.has(id)) continue;
