353	  if (myRoster) self.position.set(myRoster.x, myRoster.y, myRoster.z);
354	
355	  const applyWorldSync = (sync: WorldSync) => {
356	    // A (re)sync follows a gap that is not jitter — don't let it poison the window.
357	    delayCtl.reset();
358	    // The sync is a full keyframe: nothing pending survives it (and the block
359	    // diff it carries is truth, not an echo to suppress).
360	    ledger.clear();
361	    state.blockChanges.applySavedChanges(sync.changes);
362	    state.worldMeshDirty = true;
363	    state.dayClock = sync.dayClock;
364	    serverTickTimeMs = sync.tick * TICK_SECONDS * 1000;
365	    state.containers.clear();
366	    for (const entry of sync.blockEntities) {
367	      const restored = restoreInventorySlots({ id: "container", inventorySlots: entry.slots });
368	      if (restored) state.containers.set(entry.index, restored);
369	    }
370	    state.lootedWorldgenChests = new Set(sync.lootedChests);
371	    state.mobs = [];
372	    mobBuffers.clear();
373	    for (const pose of sync.liveMobs) upsertReplicaMob(pose);
374	    // Vehicles and in-flight arrows are replicated in (never simulated on the
375	    // replica); the join sync is their keyframe. Both were dropped in v1.
376	    state.vehicles = [];
377	    for (const pose of sync.vehicles) upsertReplicaVehicle(pose);
378	    applyProjectiles(sync.projectiles);
379	    applyRoster(sync.players);
380	  };
381	
382	  function upsertReplicaVehicle(pose: VehiclePose): void {
383	    const kind = (pose.kind === "ship" || pose.kind === "minecart" ? pose.kind : "raft") as VehicleKind;
384	    let vehicle = state.vehicles.find((v) => v.id === pose.id);
385	    if (!vehicle) {
386	      vehicle = { id: pose.id, kind, position: new THREE.Vector3(pose.x, pose.y, pose.z), yaw: pose.yaw, rider: pose.riderId };
387	      state.vehicles.push(vehicle);
388	    } else {
389	      vehicle.position.set(pose.x, pose.y, pose.z);
390	      vehicle.yaw = pose.yaw;
391	      vehicle.rider = pose.riderId;
392	    }
393	  }
394	
395	  // Arrows snap per frame (they outrun the ~125 ms interpolation delay). Each
396	  // tick carries the FULL live set, so absence prunes: an arrow no longer listed
397	  // has landed/despawned server-side.
398	  function applyProjectiles(poses: ProjectilePose[]): void {
399	    const present = new Set(poses.map((p) => p.id));
400	    state.projectiles = state.projectiles.filter((p) => present.has(p.id));
401	    for (const pose of poses) upsertReplicaProjectile(pose);
402	  }
403	
404	  function upsertReplicaProjectile(pose: ProjectilePose): void {
405	    let projectile = state.projectiles.find((p) => p.id === pose.id);
406	    if (!projectile) {
407	      // Non-simulated on the replica: only position + velocity feed the visual
408	      // (which derives orientation from velocity); the rest are inert placeholders.
409	      projectile = {
410	        id: pose.id,
411	        position: new THREE.Vector3(pose.x, pose.y, pose.z),
412	        velocity: new THREE.Vector3(pose.vx, pose.vy, pose.vz),
413	        yaw: 0,
414	        pitch: 0,
415	        damage: 0,
416	        knockback: 0,
417	        fromPlayer: true,
418	        ttl: 999
419	      };
420	      state.projectiles.push(projectile);
421	    } else {
422	      projectile.position.set(pose.x, pose.y, pose.z);
423	      projectile.velocity.set(pose.vx, pose.vy, pose.vz);
424	    }
425	  }
426	
427	  function upsertReplicaMob(pose: MobPose): MobState {
428	    let mob = state.mobs.find((m) => m.id === pose.id);
429	    if (!mob) {
430	      const kind = (MOB_TEMPLATES[pose.kind as MobKind] ? pose.kind : "zombie") as MobKind;
431	      const template = MOB_TEMPLATES[kind];
432	      mob = {
433	        id: pose.id,
434	        kind,
435	        hostile: pose.hostile,
436	        faction: FACTION_BY_KIND[kind],
437	        targetId: null,
438	        retargetTimer: 0,
439	        hp: pose.hp,
440	        position: new THREE.Vector3(pose.x, pose.y, pose.z),
441	        direction: new THREE.Vector3(1, 0, 0),
442	        yaw: pose.yaw,
443	        turnTimer: 0,
444	        speed: template.speed,
445	        moveSpeed: pose.moveSpeed,
446	        detectRange: template.detectRange,
447	        attackDamage: 0,
448	        attackCooldown: 1,
449	        attackTimer: 0,
450	        halfHeight: mobHalfHeight(kind),
451	        bobSeed: pose.id * 0.7,
452	        fedTimer: 0,
453	        ageTimer: 0
454	      };
455	      state.mobs.push(mob);
456	    }
457	    mob.hp = pose.hp;
458	    mob.moveSpeed = pose.moveSpeed;
459	    let buffer = mobBuffers.get(pose.id);
460	    if (!buffer) {
461	      buffer = createPoseBuffer();
462	      mobBuffers.set(pose.id, buffer);
463	    }
464	    return mob;
465	  }
466	
467	  const applySelfDelta = (delta: SelfDelta) => {
468	    const shim = { id: self.id, ...delta };
469	    if (delta.inventorySlots) self.inventory = restoreInventorySlots(shim) ?? self.inventory;
470	    if (delta.equippedArmor) self.equippedArmor = restoreEquippedArmor(shim) ?? self.equippedArmor;
471	    if (delta.selectedSlot !== undefined) self.selectedSlot = restoreSelectedSlot(shim) ?? self.selectedSlot;
472	    if (delta.hearts !== undefined) self.hearts = delta.hearts;
473	    if (delta.hunger !== undefined) self.hunger = delta.hunger;
474	    if (delta.oxygen !== undefined) self.oxygen = delta.oxygen;
475	    if (delta.xp !== undefined) self.xp = delta.xp;
476	    if (delta.isDead !== undefined) self.isDead = delta.isDead;
477	    if (delta.respawnSeconds !== undefined) self.respawnTimer = delta.respawnSeconds;
478	    if (delta.gameMode !== undefined) self.gameMode = delta.gameMode as never;
479	    if (delta.sleeping !== undefined) self.sleeping = delta.sleeping;
480	    if (delta.effects) {
481	      self.effects.clear();
482	      for (const { id, remaining } of restoreEffects(shim)) self.effects.set(id, remaining);
483	    }
484	    // Progression is server-owned: adopt our advancement set (grow-only) and the
485	    // event-driven stat counters. play_time/distance_walked aren't sent — the
486	    // replica's recordTick accrues those locally — so a plain set() preserves them.
487	    if (delta.advancements) self.advancements = new Set(delta.advancements);
488	    if (delta.stats) for (const { id, value } of delta.stats) self.stats.set(id, value);
489	    // Mounted: the server owns our position. Adopt the mount state and snap to
490	    // the authoritative position (the replica step skips its own motion while
491	    // mountedVehicleId is set, so the boat — not prediction — drives the camera).
492	    if (delta.mountedVehicleId !== undefined) self.mountedVehicleId = delta.mountedVehicleId;
493	    if (delta.x !== undefined && delta.y !== undefined && delta.z !== undefined) {
494	      self.position.set(delta.x, delta.y, delta.z);
495	      self.velocity.set(0, 0, 0);
496	    }
497	  };
498	
499	  const cellOf = (idx: number) => {
500	    const layer = state.world.sizeX * state.world.sizeZ;
501	    const y = Math.floor(idx / layer);
502	    const rem = idx - y * layer;
503	    const z = Math.floor(rem / state.world.sizeX);
504	    const x = rem - z * state.world.sizeX;
505	    return { x, y, z };
506	  };
507	
508	  /** Hand a rejected place's stack back; a full inventory drops it silently (the next full delta reconciles). */
509	  const refundToInventory = (refund: PredictionRefund) => {
510	    const updated = adjustSlotCount(self.inventory, refund.itemId, refund.count, self.selectedSlot);
511	    if (updated) self.inventory = updated;
512	  };
513	
514	  /** Undo one predicted cell through the relight chokepoint (a predicted chest also brought a fresh container). */
515	  const revertPredictedEdit = (edit: { idx: number; block: number; prev: number }) => {
516	    const { x, y, z } = cellOf(edit.idx);
517	    if (edit.block === BlockId.Chest) state.containers.delete(edit.idx);
518	    state.blockChanges.set(x, y, z, edit.prev as never);
519	  };
520	
521	  const applyBlocks = (blocks: Array<[number, number]>) => {
522	    for (const [idx, block] of blocks) {
523	      // The journal is the authority: it confirms matching predictions (skip
524	      // the redundant rewrite) and overrides losing ones — refund now (an
525	      // inventorySlots delta in the same tick wins over this anyway) and
526	      // revert the dropped prediction's unconfirmed sibling cells (a door's
527	      // other half): the server's placement may have failed entirely, and a
528	      // same-batch server write to a reverted cell still lands afterward.
529	      const { refunds, reverts } = ledger.onJournal(idx, block);
530	      for (const refund of refunds) refundToInventory(refund);
531	      for (const edit of reverts) revertPredictedEdit(edit);
532	      const { x, y, z } = cellOf(idx);
533	      if (state.world.get(x, y, z) !== block) state.blockChanges.set(x, y, z, block as never); // relights locally too
534	    }
535	    state.blockChanges.drainEditsDetailed(); // server writes must never register as predictions
536	    if (blocks.length > 0) state.worldMeshDirty = true;
537	  };
538	
539	  // ── inbound frame processing (latency-shifted) ──────────────────────────────
540	  const onServerFrame = (data: unknown) => {
541	    traffic.inBytes += typeof data === "string" ? data.length : ((data as ArrayBuffer).byteLength ?? 0);
542	    if (simulatedLatencyMs > 0 || simulatedJitterMs > 0) {
543	      recvLine.push(() => void processServerFrame(data));
544	      return;
545	    }
546	    void processServerFrame(data);
547	  };
548	
549	  async function processServerFrame(data: unknown): Promise<void> {
550	    if (typeof data !== "string") {
551	      const sync = await gunzipWorldSync(new Uint8Array(data as ArrayBuffer));
552	      if (sync) {
553	        applyWorldSync(sync);
554	        setStatus("online");
555	      }
556	      return;
557	    }
558	    const message = decodeServerFrame(data);
559	    if (!message) return;
560	    switch (message.t) {
561	      case "tick": {
562	        delayCtl.onTickArrival(performance.now(), message.n);
563	        serverTickTimeMs = message.n * TICK_SECONDS * 1000;
564	        if (message.blocks) applyBlocks(message.blocks);
565	        if (message.day !== undefined) state.dayClock = message.day;
566	        if (message.self) applySelfDelta(message.self);
567	        for (const pose of message.pp) {
568	          upsertRemotePlayer(pose.id, names.get(pose.id) ?? "player");
569	          let buffer = playerBuffers.get(pose.id);
570	          if (!buffer) {
571	            buffer = createPoseBuffer();
572	            playerBuffers.set(pose.id, buffer);
573	          }
574	          buffer.push({ tMs: serverTickTimeMs, ...pose });
575	        }
576	        for (const pose of message.mp) {
577	          upsertReplicaMob(pose);
578	          mobBuffers.get(pose.id)?.push({ tMs: serverTickTimeMs, x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw });
579	        }
580	        if (message.vp) for (const pose of message.vp) upsertReplicaVehicle(pose);
581	        if (message.prj) applyProjectiles(message.prj);
582	        const evNow = performance.now();
583	        for (const gameEvent of message.ev) {
584	          const ev = gameEvent as AttributedGameEvent;
585	          // Own block-edit echoes at predicted cells were already presented
586	          // at click time — swallowing the echo prevents the doubled sound/
587	          // particles. Other players' edits (and own non-predicted ones)
588	          // flow through untouched.
589	          if (
590	            (ev.type === "blockPlaced" || ev.type === "blockBroken") &&
591	            ev.playerId === playerId &&
592	            ledger.shouldSuppress(state.world.index(ev.x, ev.y, ev.z), evNow)
593	          ) {
594	            continue;
595	          }
596	          // Own swing echoes: the synthetic swing already played at click time.
597	          if (ev.type === "attackSwung" && ev.playerId === playerId) continue;
598	          pendingEvents.push(ev);
599	          callbacks.onEvent?.(ev);
600	        }
601	        return;
602	      }
603	      case "mobsKeyframe": {
604	        const alive = new Set(message.mobs.map((m) => m.id));
605	        state.mobs = state.mobs.filter((m) => alive.has(m.id));
606	        for (const id of [...mobBuffers.keys()]) if (!alive.has(id)) mobBuffers.delete(id);
607	        const tMs = message.n * TICK_SECONDS * 1000;
608	        for (const pose of message.mobs) {
609	          upsertReplicaMob(pose);
610	          mobBuffers.get(pose.id)?.push({ tMs, x: pose.x, y: pose.y, z: pose.z, yaw: pose.yaw });
611	        }
612	        return;
613	      }
614	      case "playerJoined": {
615	        upsertRemotePlayer(message.player.id, message.player.name);
616	        const joined = state.players.get(message.player.id);
617	        joined?.position.set(message.player.x, message.player.y, message.player.z);
618	        return;
619	      }
620	      case "playerLeft": {
621	        if (message.id !== playerId) engine.removePlayer(message.id);
622	        playerBuffers.delete(message.id);
623	        dropRosterEchoes();
624	        notifyRoster();
625	        return;
626	      }
627	      case "container": {
628	        const restored = restoreInventorySlots({ id: "container", inventorySlots: message.slots });
629	        if (restored) state.containers.set(message.index, restored);
630	        return;
631	      }
632	      case "chat":
633	        callbacks.onChat?.(message);
634	        for (const listener of chatListeners) listener(message);
635	        return;
636	      case "pong":
637	        clock.onPong(message.tMs, performance.now(), message.serverTick);
638	        return;
639	      case "forcePose":
640	        self.position.set(message.x, message.y, message.z);
641	        self.velocity.set(0, 0, 0);
642	        return;
643	      case "welcome":
644	        return;
645	    }
646	  }
647	
648	  // ── reconnect ladder ────────────────────────────────────────────────────────
649	  let reconnectAttempt = 0;
650	  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
651	
652	  const onSocketClosed = (code: number, reason: string) => {
653	    if (disposed) return;
654	    if (FATAL_CLOSES.has(code) || !options.reconnect) {
655	      setStatus("closed", `${code} ${reason}`);
656	      return;
657	    }
658	    scheduleReconnect();
659	  };
660	
661	  const scheduleReconnect = () => {
662	    if (disposed) return;
663	    if (reconnectAttempt >= RECONNECT_DELAYS_MS.length) {
664	      setStatus("closed", "could not reconnect");
665	      return;
666	    }
667	    const delay = RECONNECT_DELAYS_MS[reconnectAttempt];
668	    reconnectAttempt += 1;
669	    setStatus("reconnecting", `attempt ${reconnectAttempt}`);
670	    reconnectTimer = setTimeout(() => void tryReconnectOnce(), delay);
671	  };
672	
673	  async function tryReconnectOnce(): Promise<void> {
674	    if (disposed || !options.reconnect) return;
675	    const grant = await options.reconnect();
676	    if (disposed) return;
677	    if (!grant) {
678	      scheduleReconnect();
679	      return;
680	    }
681	    try {
682	      const resumed = await handshake(grant.ticket, grant.url);
683	      if (disposed) return;
684	      // Same room, same id: keep the replica; the world-sync that follows
685	      // re-seeds it. Just refresh the roster and the server-time anchor.
686	      serverTickTimeMs = resumed.tick * TICK_SECONDS * 1000;
687	      applyRoster(resumed.players);
688	      reconnectAttempt = 0;
689	      setStatus("syncing");
690	    } catch {
691	      scheduleReconnect();
692	    }
693	  }
694	
695	  // ── outbound ────────────────────────────────────────────────────────────────
696	  let seq = 0;
697	  let lastPoseSentMs = 0;
698	  let lastPingMs = 0;
699	  /** The last frame's interpolation render time (server timeline ms) — the attack view stamp. Null until the clock syncs. */
700	  let lastRenderTimeMs: number | null = null;
701	
702	  const sendCmd = (command: Command) => {
703	    seq += 1;
704	    // Foot position (matching the pose stream): the server clamps it into
705	    // player.position, then the engine derives the eye/aim ray from it by
706	    // adding EYE_HEIGHT — sending eye height here would double that offset.
707	    // Attacks additionally carry the render-time view stamp so the server can
708	    // rewind melee target selection to what this player saw (bounded there).
709	    delayedSend(
710	      encodeClientMessage({
711	        t: "cmd",
712	        seq,
713	        d: state.dimension,
714	        cmd: command,
715	        pose: { x: qPos(self.position.x), y: qPos(self.position.y), z: qPos(self.position.z), yaw: qAng(self.yaw), pitch: qAng(self.pitch) },
716	        ...(command.type === "attack" && lastRenderTimeMs !== null ? { view: Math.round(Math.max(0, lastRenderTimeMs)) } : {})
717	      })
718	    );
719	  };
720	
721	  const session: NetworkSession = {
722	    engine,
723	    playerId,
724	    role: welcome.role,
725	    subscribeChat(listener) {
726	      chatListeners.add(listener);
727	      return () => chatListeners.delete(listener);
728	    },
729	    subscribeStatus(listener) {
730	      statusListeners.add(listener);
731	      return () => statusListeners.delete(listener);
732	    },
733	    subscribeRoster(listener) {
734	      rosterListeners.add(listener);
735	      return () => rosterListeners.delete(listener);
736	    },
737	    roster: () => [...state.players.keys()].map((id) => ({ id, name: names.get(id) ?? "player" })),
738	    kick(targetId) {
739	      if (targetId !== playerId) delayedSend(encodeClientMessage({ t: "kick", targetId }));
740	    },
741	    drainEvents: () => pendingEvents.splice(0, pendingEvents.length),
742	    status: () => status,
743	    rttMs: () => clock.rttMs(),
744	    playerName: (id) => names.get(id) ?? "player",
745	
746	    dispatch(command) {
747	      engine.dispatch(command); // routeDispatch handles the local/network split
748	    },
749	
750	    applyLook(deltaYaw, deltaPitch) {
751	      engine.applyLook(deltaYaw, deltaPitch);
752	    },
753	
754	    sendChat(text) {
755	      if (text.trim()) delayedSend(encodeClientMessage({ t: "chat", text: text.slice(0, 256) }));
756	    },
757	
758	    setSimulatedLatency(ms, jitterMs) {
759	      simulatedLatencyMs = Math.max(0, Math.floor(ms));
760	      simulatedJitterMs = Math.max(0, Math.floor(jitterMs ?? 0));
761	    },
762	    simulatedLatency: () => simulatedLatencyMs,
763	    simulatedJitter: () => simulatedJitterMs,
764	
765	    netStats: () => ({
766	      rttMs: clock.rttMs(),
767	      jitterMs: delayCtl.jitterMs(),
768	      interpDelayMs: delayCtl.currentDelayMs(),
769	      inKBps: traffic.inKBps,
770	      outKBps: traffic.outKBps,
771	      pendingPredictions: ledger.size()
772	    }),
773	
774	    afterFrame(nowMs) {
775	      rollTrafficWindow(nowMs);
776	      const socketOpen = ws?.readyState === WebSocket.OPEN;
777	      // Predictive-mining capture: any journal entries at this point are
778	      // breaks the replica step just committed (placement and server writes
779	      // drain inline where they happen). While disconnected the server can't
780	      // hear the mineHeld stream, so an offline break would ghost forever —
781	      // undo it on the spot instead of ledgering it.
782	      const mined = state.blockChanges.drainEditsDetailed().filter((e) => e.block !== e.prev);
783	      if (mined.length > 0) {
784	        if (socketOpen && status === "online") {
785	          ledger.add("break", mined, null, performance.now(), clock.rttMs());
786	        } else {
787	          for (const edit of [...mined].reverse()) {
788	            const { x, y, z } = cellOf(edit.idx);
789	            state.blockChanges.set(x, y, z, edit.prev as never);
790	          }
791	          state.blockChanges.drainEditsDetailed();
792	          state.worldMeshDirty = true;
793	        }
794	      }
795	      // Expired predictions: the server neither confirmed nor overrode in
796	      // time (a rejected place, a lost cmd). Revert newest-first through the
797	      // same chokepoint that applied them — relighting rides along — and hand
798	      // the stack back. The echo-suppress window deliberately outlives this:
799	      // a late confirm re-applies via the journal without a doubled sound.
800	      for (const prediction of ledger.expire(performance.now())) {
801	        for (const edit of [...prediction.edits].reverse()) {
802	          if (!edit.confirmed) revertPredictedEdit(edit);
803	        }
804	        if (prediction.refund) refundToInventory(prediction.refund);
805	        state.blockChanges.drainEditsDetailed(); // reverts aren't predictions either
806	        state.worldMeshDirty = true;
807	      }
808	      const open = socketOpen;
809	      // Pose stream at tick rate.
810	      if (open && nowMs - lastPoseSentMs >= TICK_SECONDS * 1000) {
811	        lastPoseSentMs = nowMs;
812	        seq += 1;
813	        delayedSend(
814	          encodeClientMessage({
815	            t: "pose",
816	            seq,
817	            d: state.dimension,
818	            x: qPos(self.position.x),
819	            y: qPos(self.position.y),
820	            z: qPos(self.position.z),
821	            yaw: qAng(self.yaw),
822	            pitch: qAng(self.pitch),
823	            onGround: self.onGround,
824	            move: self.input.move,
825	            mineHeld: self.input.mineHeld
826	          })
827	        );
828	      }
829	      if (open && nowMs - lastPingMs >= PING_INTERVAL_MS) {
830	        lastPingMs = nowMs;
831	        delayedSend(encodeClientMessage({ t: "ping", id: seq, tMs: nowMs }));
832	      }
833	      // Interpolation: remote entities render in the past, far enough to
834	      // absorb the measured arrival jitter (adaptive, slewed — no warping).
835	      const renderTime = (clock.ready() ? clock.estimatedServerTimeMs(nowMs) : serverTickTimeMs) - delayCtl.effectiveDelayMs(nowMs);
836	      // The view stamp for lag compensation: a click lands between frames, so
837	      // the mobs on screen are the ones THIS sample time drew. Only trusted
838	      // once the clock is synced — until then attacks go out unstamped.
839	      if (clock.ready()) lastRenderTimeMs = renderTime;
840	      for (const [id, buffer] of playerBuffers) {
841	        const player = state.players.get(id);
842	        const pose = buffer.sample(renderTime);
843	        if (player && pose) {
844	          player.position.set(pose.x, pose.y, pose.z);
845	          player.yaw = pose.yaw;
846	          player.pitch = pose.pitch;
847	        }
848	      }
849	      for (const [id, buffer] of mobBuffers) {
850	        const mob = state.mobs.find((m) => m.id === id);
851	        const pose = buffer.sample(renderTime);
852	        if (mob && pose) {
853	          mob.position.set(pose.x, pose.y, pose.z);
854	          mob.yaw = pose.yaw;
855	        }
856	      }
857	    },
858	
859	    dispose() {
860	      disposed = true;
861	      if (reconnectTimer) clearTimeout(reconnectTimer);
862	      sendLine.clear();
863	      recvLine.clear();
864	      setStatus("closed", "left world");
865	      try {
866	        ws?.close(1000, "leaving");
867	      } catch {
868	        /* already closed */
869	      }
870	    }
871	  };
872	  return session;
873	}
