1	import { describe, expect, test } from "bun:test";
2	import { connectNetworkSession, type JoinGrant, type NetworkSession } from "./NetworkSession";
3	import { BlockId } from "@/lib/world";
4	import { createSlot } from "@/lib/game/items";
5	import { frameInput } from "@/lib/game/engine/testSupport";
6	import { gzipWorldSync } from "./codec";
7	import type { SelfDelta, WelcomeMessage, WorldSync } from "./protocol";
8	
9	/**
10	 * The client session end-to-end against a scriptable fake socket: the
11	 * handshake, command routing (local vs networked), self-delta application,
12	 * chat, the simulated-latency knob, and — the Phase 6 headline — the
13	 * reconnect ladder resuming the SAME replica after a non-fatal drop. Driving
14	 * a real browser socket-kill would be flaky; a fake makes every edge
15	 * deterministic (the server half is covered by server/room.test.ts).
16	 */
17	
18	/** A tiny replica world keeps each test's worldgen fast (the real footprint is 512²). */
19	const SMALL = { x: 32, y: 64, z: 32 };
20	
21	const WELCOME: WelcomeMessage = {
22	  t: "welcome",
23	  protocol: 1,
24	  playerId: "acct-1",
25	  worldId: "w1",
26	  seed: 1337,
27	  // Superflat keeps each test's replica worldgen cheap (no noise/caves) at the
28	  // real 512² footprint — the routing/reconnect logic under test is size-blind.
29	  worldType: "flat",
30	  difficulty: "normal",
31	  hardcore: false,
32	  dayClock: 60,
33	  tick: 100,
34	  role: "owner",
35	  dimension: "overworld" as const,
36	  players: [{ id: "acct-1", name: "Alpha", skinId: null, dim: "overworld" as const, x: 5, y: 40, z: 5, yaw: 0 }]
37	};
38	
39	function worldSync(players: WorldSync["players"], overrides: Partial<WorldSync> = {}): WorldSync {
40	  return {
41	    t: "worldSync",
42	    tick: 100,
43	    dimension: "overworld",
44	    dayClock: 60,
45	    changes: [],
46	    blockEntities: [],
47	    lootedChests: [],
48	    mobs: [],
49	    liveMobs: [],
50	    vehicles: [],
51	    projectiles: [],
52	    players,
53	    ...overrides
54	  };
55	}
56	
57	/** A minimal scriptable WebSocket: auto-answers the hello with a welcome, records sends, lets the test emit frames. */
58	class FakeSocket {
59	  static OPEN = 1;
60	  readyState = 0;
61	  binaryType = "blob";
62	  onopen: (() => void) | null = null;
63	  onmessage: ((event: { data: unknown }) => void) | null = null;
64	  onclose: ((event: { code: number; reason: string }) => void) | null = null;
65	  onerror: (() => void) | null = null;
66	  readonly sent: string[] = [];
67	
68	  constructor(
69	    public url: string,
70	    private readonly welcome: WelcomeMessage
71	  ) {
72	    queueMicrotask(() => {
73	      this.readyState = 1;
74	      this.onopen?.();
75	    });
76	  }
77	
78	  send(data: string): void {
79	    this.sent.push(data);
80	    const message = JSON.parse(data) as { t: string };
81	    if (message.t === "hello") this.onmessage?.({ data: JSON.stringify(this.welcome) });
82	  }
83	
84	  emit(data: unknown): void {
85	    this.onmessage?.({ data });
86	  }
87	
88	  emitClose(code: number, reason = ""): void {
89	    this.readyState = 3;
90	    this.onclose?.({ code, reason });
91	  }
92	
93	  close(code = 1000, reason = ""): void {
94	    this.emitClose(code, reason);
95	  }
96	
97	  sentTypes(): string[] {
98	    return this.sent.map((s) => (JSON.parse(s) as { t: string }).t);
99	  }
100	}
101	
102	function socketFactory(welcome: WelcomeMessage = WELCOME) {
103	  const instances: FakeSocket[] = [];
104	  const make = (url: string) => {
105	    const socket = new FakeSocket(url, welcome);
106	    instances.push(socket);
107	    return socket as unknown as WebSocket;
108	  };
109	  return { make, instances };
110	}
111	
112	async function pushWorldSync(socket: FakeSocket, sync: WorldSync): Promise<void> {
113	  const gz = await gzipWorldSync(sync);
114	  socket.emit(gz.buffer.slice(gz.byteOffset, gz.byteOffset + gz.byteLength));
115	  await Promise.resolve(); // let the async gunzip settle
116	  await Promise.resolve();
117	}
118	
119	const tick = (self?: SelfDelta, extra: Record<string, unknown> = {}) =>
120	  JSON.stringify({ t: "tick", n: 101, ev: [], pp: [], mp: [], ...extra, ...(self ? { self } : {}) });
121	
122	describe("connectNetworkSession", () => {
123	  test("handshakes, syncs, and mounts a replica engine seeded from the welcome", async () => {
124	    const { make, instances } = socketFactory();
125	    const session = await connectNetworkSession("ws://game", "ticket-1", {}, { makeSocket: make, worldSize: SMALL });
126	
127	    expect(session.playerId).toBe("acct-1");
128	    expect(instances[0].sentTypes()[0]).toBe("hello");
129	    expect(session.status()).toBe("syncing");
130	
131	    await pushWorldSync(instances[0], worldSync(WELCOME.players));
132	    expect(session.status()).toBe("online");
133	    expect(session.engine.state.world.seed).toBe(1337);
134	    session.dispose();
135	  });
136	
137	  test("routes gameplay commands to the wire but keeps presentation on the replica", async () => {
138	    const { make, instances } = socketFactory();
139	    const session = await connectNetworkSession("ws://game", "ticket-1", {}, { makeSocket: make, worldSize: SMALL });
140	    await pushWorldSync(instances[0], worldSync(WELCOME.players));

