1	import { expect, test, type Page } from "@playwright/test";
2	
3	/**
4	 * The full co-op journey against the real online stack: the Next app backed
5	 * by an in-process Postgres (DATABASE_URL=pglite://memory) plus the Bun game
6	 * server, both from playwright.config's webServer list — no Docker, no cloud.
7	 * Two isolated browser contexts play two ACCOUNTS (online play is
8	 * accounts-only): the host registers, creates an online profile and world
9	 * through the account menus, the friend registers on the invite landing page,
10	 * and the pair must see each other, share block edits, and chat.
11	 */
12	
13	/** Console/page errors collected like the smoke fixture does (favicon 404 is noise). */
14	function watchErrors(page: Page, sink: string[]): void {
15	  page.on("console", (message) => {
16	    if (message.type() !== "error") return;
17	    if (message.text().includes("Failed to load resource") && message.location().url.endsWith("/favicon.ico")) return;
18	    sink.push(`${message.text()} (${message.location().url})`);
19	  });
20	  page.on("pageerror", (error) => sink.push(String(error)));
21	}
22	
23	/** Booted, synced, and drawing: the bar every online entry must clear. */
24	async function waitForOnlineGame(page: Page): Promise<void> {
25	  await page.waitForFunction(() => window.__monecraft !== undefined, undefined, { timeout: 30000 });
26	  await page.waitForFunction(() => window.__monecraft!.net?.status() === "online", undefined, { timeout: 30000 });
27	  await page.waitForFunction(() => window.__monecraft!.renderer.renderedTriangles() > 0, undefined, { timeout: 30000 });
28	}
29	
30	/** Registers a fresh account: welcome gate's "Sign in" → auth screen → sign-up. */
31	async function signUp(page: Page, name: string, email: string): Promise<void> {
32	  await page.getByRole("button", { name: "Sign in", exact: true }).click();
33	  await page.getByRole("button", { name: "I need an account" }).click();
34	  await page.getByLabel("Email").fill(email);
35	  await page.getByLabel("Display name").fill(name);
36	  await page.getByLabel("Password").fill("hunter2hunter2");
37	  await page.getByRole("button", { name: "Create account" }).click();
38	}
39	
40	/** From the account home, creates an online profile and enters its world list. */
41	async function createOnlineProfile(page: Page, name: string): Promise<void> {
42	  // Sign-up → session probe → account home spans two network hops.
43	  await expect(page.getByText("Online Profiles")).toBeVisible({ timeout: 15000 });
44	  await page.getByTestId("new-online-profile").click();
45	  await page.getByLabel("Profile name").fill(name);
46	  // exact: "Create account" (form) and "Create World" share the substring.
47	  await page.getByRole("button", { name: "Create", exact: true }).click();
48	}
49	
50	/**
51	 * Opens the engine input gate with the STABLE forced flag (never REAL pointer
52	 * lock) and aims straight down, ready for a held `mouse.down()` dig. Real lock
53	 * is flaky under automation — new-headless can win it then drop it mid-hold,
54	 * and the resulting pointerlockchange resets `pointerLocked`, so a long-held
55	 * dig quietly stops (it shows up as the block never breaking, "Double-click to
56	 * play" back). The forced flag never fires pointerlockchange, so the dig stays
57	 * engaged across the poll. Mirrors what helpers.acquirePointerLock falls back
58	 * to, minus the flaky real-lock attempt.
59	 */
60	async function forceDigStraightDown(page: Page): Promise<void> {
61	  await page.locator(".game-canvas-wrap canvas").hover();
62	  // Wait until the player has actually landed. A just-spawned player is still
63	  // settling, and aiming straight down while airborne can overshoot the terrain
64	  // (the down-ray finds no block in reach), so the held dig never engages mining
65	  // — the deepest of this test's old flakes (the block-edit poll timing out at
66	  // 0). Grounded, the block underfoot is always a valid target.
67	  await page.waitForFunction(() => window.__monecraft!.engine.state.player.onGround === true, undefined, { timeout: 20000 });
68	  await page.evaluate(() => {
69	    window.__monecraft!.input.forcePointerLock(true);
70	    window.__monecraft!.engine.state.player.pitch = -Math.PI / 2 + 0.02;
71	  });
72	}
73	
74	test("two accounts share an online world via an invite link", async ({ browser }) => {
75	  // Two production builds of the game plus a WebSocket handshake each; CI
76	  // renders with software GL, so the whole journey gets a generous ceiling. A
77	  // slammed shared runner has overrun 240s here (the registration journey and
78	  // the edit-propagation polls both run long under load), so give it 5 min.
79	  test.setTimeout(300000);
80	  const errors: string[] = [];
81	  // The pglite webServer keeps its data across retries within one run, so a
82	  // fixed email means every retry dies on "User already exists" — tag them.
83	  const runTag = Date.now().toString(36);
84	
85	  // ── the host: register → online profile → online world → in-game ─────────
86	  const hostContext = await browser.newContext();
87	  const host = await hostContext.newPage();
88	  watchErrors(host, errors);
89	  await host.goto("/");
90	
91	  // The welcome gate's "Sign in" leads straight to the auth screen, so
92	  // registration needs no local profile — a pure account never touches the
93	  // local menus.
94	  await signUp(host, "Hosta", `host-${runTag}@example.com`);
95	  await createOnlineProfile(host, "Hosta");
96	
97	  // Creative, so the host's block breaks are instant on the server side.
98	  await host.getByTestId("new-online-world").click();
99	  await host.getByLabel("World name").fill("Co-op Test");
100	  await host.getByLabel("World seed").fill("4242");
101	  await host.getByRole("button", { name: "Creative mode" }).click();
102	  await host.getByRole("button", { name: "Create World" }).click();
103	  await waitForOnlineGame(host);
104	
105	  // Mint the invite with the host's cookies (the menu's Copy button wraps the
106	  // same endpoint; the clipboard is out of reach in headless runs).
107	  const worldId = await host.evaluate(async () => {
108	    const response = await fetch("/api/worlds");
109	    const { worlds } = (await response.json()) as { worlds: Array<{ id: string }> };
110	    return worlds[0].id;
111	  });
112	  const inviteToken = await host.evaluate(async (id) => {
113	    const response = await fetch(`/api/worlds/${id}/invites`, { method: "POST" });
114	    const { token } = (await response.json()) as { token: string };
115	    return token;
116	  }, worldId);
117	
118	  // ── the friend: invite link → register on the landing page → same world ──
119	  const friendContext = await browser.newContext();
120	  const friend = await friendContext.newPage();
121	  watchErrors(friend, errors);
122	  await friend.goto(`/join/${inviteToken}`);
123	
124	  // The landing page previews the world before any sign-in, then embeds the
125	  // account panel; registering accepts the invite in place.
126	  await expect(friend.getByText("Co-op Test")).toBeVisible({ timeout: 15000 });
127	  await expect(friend.getByText(/sign in to join/)).toBeVisible();
128	  await signUp(friend, "Frienda", `friend-${runTag}@example.com`);
129	  await expect(friend.getByText(/You've joined/)).toBeVisible({ timeout: 15000 });
130	  await friend.getByRole("link", { name: "Open the game" }).click();
131	
132	  // The landing page marked online-used, so the shell finds the fresh session
133	  // and opens the account home. The joined world surfaces under any profile
134	  // (membership is account-level), labelled as joined rather than owned.
135	  await createOnlineProfile(friend, "Friend");
136	  await expect(friend.getByTestId(`online-world-${worldId}`)).toContainText("Joined");
137	  await friend.getByTestId(`online-world-${worldId}`).click();
138	  await waitForOnlineGame(friend);
139	
140	  // ── both replicas agree there are two players in the room ────────────────
141	  for (const page of [host, friend]) {
142	    await page.waitForFunction(() => window.__monecraft!.engine.state.players.size === 2, undefined, { timeout: 15000 });
143	  }
144	
