import { expect, test, type Page } from "@playwright/test";
import { createOnlineProfile, signUp, waitForOnlineGame, watchErrors } from "./onlineHelpers";

/**
 * Nether travel in an ONLINE world, end-to-end through the real stack: the
 * host builds and ignites a portal with real networked placeBlock commands
 * (every obsidian cell is confirmed by the server's journal echo), dwells,
 * and the server hands them to a lazily-born nether shard — the client swaps
 * its replica and renderer around the SAME live socket. The friend watches
 * the roster tag flip, follows through, both meet in the nether, and the
 * host rides the arrival portal home. Superflat + creative keeps the frame
 * geometry deterministic (level ground, free blocks, no hostile aggro).
 */

/** Aims the replica player's eye ray at a world point (yaw/pitch convention from lookDirection). */
async function aimAt(page: Page, target: { x: number; y: number; z: number }): Promise<void> {
  await page.evaluate((t) => {
    const s = window.__monecraft!.engine.state;
    const eye = { x: s.player.position.x, y: s.player.position.y + 1.62, z: s.player.position.z };
    const dx = t.x - eye.x;
    const dy = t.y - eye.y;
    const dz = t.z - eye.z;
    const len = Math.hypot(dx, dy, dz);
    s.player.pitch = Math.asin(dy / len);
    s.player.yaw = Math.atan2(-dx, -dz);
  }, target);
}

/**
 * Moves the (flying) player in ≤3-block hops the server's pose clamps accept
 * (creative flight is `free` movement server-side — FLY_SPEED×1.6×elapsed —
 * and elapsed accrues between accepted poses, so short hops with pauses pass).
 */
async function flyTo(page: Page, target: { x: number; y: number; z: number }): Promise<void> {
  for (let hop = 0; hop < 60; hop += 1) {
    const done = await page.evaluate((t) => {
      const p = window.__monecraft!.engine.state.player;
      const dx = t.x - p.position.x;
      const dy = t.y - p.position.y;
      const dz = t.z - p.position.z;
      const dist = Math.hypot(dx, dy, dz);
      if (dist < 0.3) return true;
      const step = Math.min(3, dist);
      p.position.set(p.position.x + (dx / dist) * step, p.position.y + (dy / dist) * step, p.position.z + (dz / dist) * step);
      p.velocity.set(0, 0, 0);
      return false;
    }, target);
    if (done) return;
    await page.waitForTimeout(250); // let the pose stream carry the hop
  }
  throw new Error(`could not reach ${JSON.stringify(target)}`);
}

/**
 * Places the selected block at a cell through the REAL wire path (aim → the
 * routed placeBlock cmd → server raycast → journal echo), confirming the
 * server's world changed before returning. Aim candidates cover the two
 * support geometries: onto the top face of the block below, or out of the
 * side face of a horizontal neighbor.
 */
async function placeAt(page: Page, cell: { x: number; y: number; z: number }, blockId: number, aims: Array<{ x: number; y: number; z: number }>): Promise<void> {
  for (const aim of aims) {
    await aimAt(page, aim);
    await page.waitForTimeout(150); // the cmd carries the claimed pose; let the stream settle first
    await page.evaluate(() => window.__monecraft!.net!.dispatch({ type: "placeBlock" }));
    try {
      await expect
        .poll(() => page.evaluate((c) => window.__monecraft!.engine.state.world.get(c.x, c.y, c.z), cell), { timeout: 8000 })
        .toBe(blockId);
      return;
    } catch {
      /* the ray clipped a different face — try the next candidate */
    }
  }
  throw new Error(`could not place block ${blockId} at ${JSON.stringify(cell)}`);
}

/** Polls the (possibly mid-remount) game handle for the current dimension. */
const dimensionOf = (page: Page) => page.evaluate(() => window.__monecraft?.engine?.state?.dimension ?? "swapping");

/** Selects the hotbar slot holding an item (waits for the SelfDelta to deliver it first). */
async function selectItem(page: Page, itemId: string): Promise<void> {
  await expect
    .poll(() => page.evaluate((id) => window.__monecraft!.engine.state.player.inventory.findIndex((slot) => slot?.id === id), itemId), { timeout: 10000 })
    .toBeGreaterThanOrEqual(0);
  await page.evaluate((id) => {
    const s = window.__monecraft!.engine.state;
    const index = s.player.inventory.findIndex((slot) => slot?.id === id);
    window.__monecraft!.net!.dispatch({ type: "selectSlot", index });
  }, itemId);
}

