2	import { db as liveDb, schema, type Db } from "@/db";
3	import { readSave } from "@/lib/game/save";
4	import type { SaveData } from "@/lib/game/types";
5	import { gunzipWorldSync } from "@/lib/net/codec";
6	
7	/**
8	 * Room persistence: where a world's row and gzipped v17 save blob live.
9	 * Postgres (the same tables the web API writes) in production; the in-memory
10	 * adapter backs tests and PERSISTENCE=memory mode (DB-less local iteration
11	 * and the Playwright multiplayer spec — unknown world ids are auto-created
12	 * with a seed derived from the id).
13	 */
14	
15	export type WorldRecord = {
16	  id: string;
17	  seed: number;
18	  worldType: string;
19	  difficulty: string;
20	  hardcore: boolean;
21	  save: SaveData | null;
22	};
23	
24	export type Persistence = {
25	  loadWorld(worldId: string): Promise<WorldRecord | null>;
26	  storeWorld(worldId: string, blob: Uint8Array, saveVersion: number): Promise<void>;
27	};
28	
29	/** Parses a stored gzipped SaveData blob through the full readSave validation/migration chain. */
30	export async function parseSaveBlob(blob: Uint8Array): Promise<SaveData | null> {
31	  try {
32	    // Reuse gunzip; then readSave via a one-key Storage shim so the entire
33	    // migration + validation pipeline applies to server-loaded saves too.
34	    const bun = typeof Bun !== "undefined" ? (Bun as unknown as { gunzipSync(d: Uint8Array): Uint8Array }) : null;
35	    const json = bun ? new TextDecoder().decode(bun.gunzipSync(blob)) : JSON.stringify(await gunzipWorldSync(blob)); // never taken on Bun; keeps the module portable
36	    const shim = { getItem: () => json } as unknown as Storage;
37	    return readSave("blob", shim);
38	  } catch {
39	    return null;
40	  }
41	}
42	
43	export function createDrizzlePersistence(database: Db = liveDb()): Persistence {
44	  return {
45	    async loadWorld(worldId) {
46	      const [row] = await database.select().from(schema.worlds).where(eq(schema.worlds.id, worldId));
47	      if (!row) return null;
48	      return {
49	        id: row.id,
