import { GameEngine } from "@/lib/game/engine/GameEngine";
import { createSlot } from "@/lib/game/items";

// Reproduces the nether-online e2e's frame-build geometry on a flat world:
// stand at one spot, aim at each support, placeBlock, verify the landed cell.

function aim(state: any, t: { x: number; y: number; z: number }) {
  const eye = { x: state.player.position.x, y: state.player.position.y + 1.62, z: state.player.position.z };
  const dx = t.x - eye.x, dy = t.y - eye.y, dz = t.z - eye.z;
  const len = Math.hypot(dx, dy, dz);
  state.player.pitch = Math.asin(dy / len);
  state.player.yaw = Math.atan2(-dx, -dz);
}

test("frame build geometry from one stand", () => {
  const e = new GameEngine({ seed: 4242, worldType: "flat", gameMode: "creative", worldSize: { x: 64, y: 80, z: 64 } });
  const s = e.state as any;
  const px = 32, pz = 32;
  const zp = pz - 3;
  const g = s.world.highestSolidY(px, zp);
  console.log("ground g =", g);
  // Stand on the ground at the build spot.
  s.player.position.set(px + 0.5, g + 1, pz + 0.5);
  s.player.velocity.set(0, 0, 0);
  s.player.isFlying = true;
  // Obsidian in hand.
  const slot = s.inventory.findIndex((x: any) => !x.id);
  s.inventory = [...s.inventory];
  s.inventory[slot] = createSlot("obsidian", 64);
  e.dispatch({ type: "selectSlot", index: slot });

  const placed: string[] = [];
  const tryPlace = (cell: { x: number; y: number; z: number }, aims: Array<{ x: number; y: number; z: number }>, feetY: number) => {
    s.player.position.set(px + 0.5, feetY, pz + 0.5);
    for (const a of aims) {
      aim(s, a);
      e.dispatch({ type: "placeBlock" });
      if (s.world.get(cell.x, cell.y, cell.z) === 90) { placed.push(JSON.stringify(cell)); return true; }
    }
    console.log("FAILED", cell, "world around:", [-1,0,1].map(dy => s.world.get(cell.x, cell.y+dy, cell.z)));
    return false;
  };

  const topAims = (x: number, y: number, z: number) => [
    { x: x + 0.5, y: y - 0.05, z: z + 0.5 },
    { x: x + 0.5, y: y - 0.2, z: z + 0.5 }
  ];

  let ok = true;
  for (let row = 0; row <= 4; row += 1) {
    const y = g + 1 + row;
    const cols = row === 0 || row === 4 ? [-1, 0, 1, 2] : [-1, 2];
    for (const i of cols) {
      if (row === 4 && (i === 0 || i === 1)) continue;
      ok = tryPlace({ x: px + i, y, z: zp }, topAims(px + i, y, zp), y) && ok;
    }
  }
  ok = tryPlace({ x: px, y: g + 5, z: zp }, [{ x: px - 0.1, y: g + 5.5, z: zp + 0.5 }], g + 4.4) && ok;
  ok = tryPlace({ x: px + 1, y: g + 5, z: zp }, [{ x: px + 2.1, y: g + 5.5, z: zp + 0.5 }], g + 4.4) && ok;
  console.log("placed:", placed.length);
  expect(ok).toBe(true);

  // Ignition: flint & steel aimed at the bottom bar's top face under an interior cell.
  s.player.position.set(px + 0.5, g + 1, pz + 0.5);
  const fs = s.inventory.findIndex((x: any) => !x.id);
  s.inventory = [...s.inventory];
  s.inventory[fs] = createSlot("flint_and_steel", 1);
  e.dispatch({ type: "selectSlot", index: fs });
  aim(s, { x: px + 0.5, y: g + 1.95, z: zp + 0.5 });
  e.dispatch({ type: "placeBlock" });
  expect(s.world.get(px, g + 2, zp)).toBe(91);
});

