/**
 * Moves the (flying) player in ≤3-block hops the server's pose clamps accept
 * (creative flight is `free` movement server-side — FLY_SPEED×1.6×elapsed —
 * and elapsed accrues between accepted poses, so short hops with pauses pass).
 */
async function flyTo(page: Page, target: { x: number; y: number; z: number }): Promise<void> {
  for (let hop = 0; hop < 60; hop += 1) {
    const done = await page.evaluate((t) => {
      const p = window.__monecraft!.engine.state.player;
      const dx = t.x - p.position.x;
      const dy = t.y - p.position.y;
      const dz = t.z - p.position.z;
      const dist = Math.hypot(dx, dy, dz);
      if (dist < 0.3) return true;
      const step = Math.min(3, dist);
      p.position.set(p.position.x + (dx / dist) * step, p.position.y + (dy / dist) * step, p.position.z + (dz / dist) * step);
      p.velocity.set(0, 0, 0);
      return false;
    }, target);
    if (done) return;
    await page.waitForTimeout(250); // let the pose stream carry the hop
  }
  throw new Error(`could not reach ${JSON.stringify(target)}`);
}

