1	import { expect, test, type Page } from "@playwright/test";
2	import { createOnlineProfile, signUp, waitForOnlineGame, watchErrors } from "./onlineHelpers";
3	
4	/**
5	 * Nether travel in an ONLINE world, end-to-end through the real stack: the
6	 * host builds and ignites a portal with real networked placeBlock commands
7	 * (every obsidian cell is confirmed by the server's journal echo), dwells,
8	 * and the server hands them to a lazily-born nether shard — the client swaps
9	 * its replica and renderer around the SAME live socket. The friend watches
10	 * the roster tag flip, follows through, both meet in the nether, and the
11	 * host rides the arrival portal home. Superflat + creative keeps the frame
12	 * geometry deterministic (level ground, free blocks, no hostile aggro).
13	 */
14	
15	/** Aims the replica player's eye ray at a world point (yaw/pitch convention from lookDirection). */
16	async function aimAt(page: Page, target: { x: number; y: number; z: number }): Promise<void> {
17	  await page.evaluate((t) => {
18	    const s = window.__monecraft!.engine.state;
19	    const eye = { x: s.player.position.x, y: s.player.position.y + 1.62, z: s.player.position.z };
20	    const dx = t.x - eye.x;
21	    const dy = t.y - eye.y;
22	    const dz = t.z - eye.z;
23	    const len = Math.hypot(dx, dy, dz);
24	    s.player.pitch = Math.asin(dy / len);
25	    s.player.yaw = Math.atan2(-dx, -dz);
26	  }, target);
27	}
28	
29	/**
30	 * Moves the (flying) player in ≤1-block hops. The 20 Hz pose stream keeps
31	 * `elapsed` at one tick server-side, so each pose may move at most
32	 * ~FLY_SPEED×1.6×0.05+0.5 ≈ 1.3 blocks — a bigger hop is refused and
33	 * force-posed back, which is exactly the stall this helper must avoid.
34	 */
35	async function flyTo(page: Page, target: { x: number; y: number; z: number }, stepSize = 1): Promise<void> {
36	  for (let hop = 0; hop < 400; hop += 1) {
37	    const done = await page.evaluate(
38	      ({ t, stepSize: size }) => {
39	        const p = window.__monecraft!.engine.state.player;
40	        const dx = t.x - p.position.x;
41	        const dy = t.y - p.position.y;
42	        const dz = t.z - p.position.z;
43	        const dist = Math.hypot(dx, dy, dz);
44	        if (dist < 0.3) return true;
45	        const step = Math.min(size, dist);
46	        p.position.set(p.position.x + (dx / dist) * step, p.position.y + (dy / dist) * step, p.position.z + (dz / dist) * step);
47	        p.velocity.set(0, 0, 0);
48	        return false;
49	      },
50	      { t: target, stepSize }
51	    );
52	    if (done) return;
53	    await page.waitForTimeout(120); // let the pose stream carry the hop
54	  }
55	  throw new Error(`could not reach ${JSON.stringify(target)}`);
56	}
57	
58	/** Ground movement: like flyTo but with sub-clamp steps — a NON-flying player's per-pose allowance is under a block at the 20 Hz cadence. */
59	const walkTo = (page: Page, target: { x: number; y: number; z: number }) => flyTo(page, target, 0.8);
60	
61	/**
62	 * Places the selected block at a cell through the REAL wire path (aim → the
63	 * routed placeBlock cmd → server raycast → journal broadcast) and confirms it
64	 * on the OTHER player's replica — the placer's own world can briefly show an
65	 * optimistic prediction the server rejected, but only a server-confirmed edit
66	 * ever reaches the witness. Aim candidates cover the two support geometries:
67	 * onto the top face of the block below, or out of a horizontal neighbor's
68	 * side face.
69	 */
70	async function placeAt(
71	  placer: Page,
72	  witness: Page,
73	  cell: { x: number; y: number; z: number },
74	  blockId: number,
75	  aims: Array<{ x: number; y: number; z: number }>
76	): Promise<void> {
77	  for (const aim of aims) {
78	    await aimAt(placer, aim);
79	    await placer.waitForTimeout(150); // the cmd carries the claimed pose; let the stream settle first
80	    await placer.evaluate(() => window.__monecraft!.net!.dispatch({ type: "placeBlock" }));
81	    try {
82	      await expect.poll(() => witness.evaluate((c) => window.__monecraft!.engine.state.world.get(c.x, c.y, c.z), cell), { timeout: 8000 }).toBe(blockId);
83	      return;
84	    } catch {
85	      /* the ray clipped a different face — try the next candidate */
86	    }
87	  }
88	  throw new Error(`could not place block ${blockId} at ${JSON.stringify(cell)}`);
89	}
90	
91	/** Polls the (possibly mid-remount) game handle for the current dimension. */
92	const dimensionOf = (page: Page) => page.evaluate(() => window.__monecraft?.engine?.state?.dimension ?? "swapping");
93	
94	/**
95	 * Puts a creative-palette item IN HAND: give → swap into a hotbar slot →
96	 * select. creativeGiveItem fills the lowest empty slot, which on a fresh
97	 * player is BEYOND the hotbar (the starter kit fills slots 0–8), and
98	 * selectSlot refuses non-hotbar indices — so the swap is load-bearing. Every
99	 * step round-trips the server (the SelfDelta echoes confirm).
100	 */
101	async function holdItem(page: Page, itemId: string, hotbarIndex: number): Promise<void> {
102	  await page.evaluate((id) => window.__monecraft!.net!.dispatch({ type: "creativeGiveItem", itemId: id }), itemId);
103	  await expect
104	    .poll(() => page.evaluate((id) => window.__monecraft!.engine.state.player.inventory.findIndex((slot) => slot?.id === id), itemId), { timeout: 10000 })
105	    .toBeGreaterThanOrEqual(0);
106	  await page.evaluate(
107	    ({ id, to }) => {
108	      const s = window.__monecraft!.engine.state;
109	      const from = s.player.inventory.findIndex((slot) => slot?.id === id);
110	      if (from !== to) window.__monecraft!.net!.dispatch({ type: "swapSlots", from, to });
111	      window.__monecraft!.net!.dispatch({ type: "selectSlot", index: to });
112	    },
113	    { id: itemId, to: hotbarIndex }
114	  );
115	  await expect
116	    .poll(() => page.evaluate((to) => window.__monecraft!.engine.state.player.inventory[to]?.id ?? null, hotbarIndex), { timeout: 10000 })
117	    .toBe(itemId);
118	}
