120	test("two players cross a nether portal in an online world and come back", async ({ browser }) => {
121	  // Two production builds, a ws handshake each, ~15 confirmed server-side
122	  // block placements, and TWO full nether worldgens (server shard + each
123	  // client replica) — the most machinery any e2e here drives.
124	  test.setTimeout(360000);
125	  const errors: string[] = [];
126	  const runTag = Date.now().toString(36);
127	
128	  // ── host: account → online profile → SUPERFLAT CREATIVE world ─────────────
129	  const hostContext = await browser.newContext();
130	  const host = await hostContext.newPage();
131	  watchErrors(host, errors);
132	  await host.goto("/");
133	  await signUp(host, "Porta", `portal-host-${runTag}@example.com`);
134	  await createOnlineProfile(host, "Porta");
135	  await host.getByTestId("new-online-world").click();
136	  await host.getByLabel("World name").fill("Nether Co-op");
137	  await host.getByLabel("World seed").fill("4242");
138	  await host.getByRole("button", { name: "Superflat world type" }).click();
139	  await host.getByRole("button", { name: "Creative mode" }).click();
140	  await host.getByRole("button", { name: "Create World" }).click();
141	  await waitForOnlineGame(host);
142	
143	  // ── friend joins via invite ────────────────────────────────────────────────
144	  const worldId = await host.evaluate(async () => {
145	    const response = await fetch("/api/worlds");
146	    const { worlds } = (await response.json()) as { worlds: Array<{ id: string }> };
147	    return worlds[0].id;
148	  });
149	  const inviteToken = await host.evaluate(async (id) => {
150	    const response = await fetch(`/api/worlds/${id}/invites`, { method: "POST" });
151	    const { token } = (await response.json()) as { token: string };
152	    return token;
153	  }, worldId);
154	  const friendContext = await browser.newContext();
155	  const friend = await friendContext.newPage();
156	  watchErrors(friend, errors);
157	  await friend.goto(`/join/${inviteToken}`);
158	  await signUp(friend, "Followa", `portal-friend-${runTag}@example.com`);

